package com.runetongue.bundler;

import com.runetongue.text.Entry;
import com.runetongue.text.ParseResult;
import com.runetongue.text.SkipReason;
import com.runetongue.text.TsvParser;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import java.util.zip.Deflater;
import java.util.zip.GZIPOutputStream;

/**
 * Build-time tool: turns {@code data/<lang>/*.tsv} into {@code com/runetongue/translations_<lang>.tsv.gz}.
 * Each file goes through the plugin's own parser; lines it would skip at runtime are left out of
 * the bundle and listed in {@code <reports>/<lang>-skipped.tsv}. Files are concatenated in name
 * order, so a later file still wins over an earlier one, as it does in the user folder.
 */
public final class BundleTranslations
{
	private BundleTranslations()
	{
	}

	public static void main(String[] args) throws IOException
	{
		Path dataRoot = Paths.get(args[0]);
		Path resourcesRoot = Paths.get(args[1]);
		Path reportRoot = Paths.get(args[2]);
		Files.createDirectories(resourcesRoot.resolve("com/runetongue"));
		Files.createDirectories(reportRoot);
		for (Path languageDir : list(dataRoot, Files::isDirectory))
		{
			String language = languageDir.getFileName().toString();
			bundle(language, list(languageDir, p -> p.toString().endsWith(".tsv")),
				resourcesRoot.resolve("com/runetongue/translations_" + language + ".tsv.gz"),
				reportRoot.resolve(language + "-skipped.tsv"));
		}
	}

	private static void bundle(String language, List<Path> files, Path out, Path report) throws IOException
	{
		String header = null;
		int kept = 0;
		int untranslated = 0;
		Map<SkipReason, Integer> skipCounts = new EnumMap<>(SkipReason.class);
		try (Writer bundle = gzipWriter(out);
			BufferedWriter skips = Files.newBufferedWriter(report, StandardCharsets.UTF_8))
		{
			skips.write("file\tline\treason\tdetail\tlineText\n");
			for (Path file : files)
			{
				byte[] bytes = Files.readAllBytes(file);
				String[] lines = new String(bytes, StandardCharsets.UTF_8).split("\r?\n", -1);
				if (header == null)
				{
					header = lines[0];
					bundle.write(header);
					bundle.write('\n');
				}
				else if (!header.equals(lines[0]))
				{
					throw new IllegalStateException(file + ": header differs from the first file's: " + lines[0]);
				}

				ParseResult result = TsvParser.parse(bytes);
				Set<Integer> keep = result.getEntries().stream().map(Entry::getLine).collect(Collectors.toSet());
				for (int i = 1; i < lines.length; i++)
				{
					if (keep.contains(i + 1))
					{
						bundle.write(lines[i]);
						bundle.write('\n');
						kept++;
					}
				}
				for (ParseResult.Skipped s : result.getSkipped())
				{
					skipCounts.merge(s.getReason(), 1, Integer::sum);
					skips.write(String.join("\t", file.getFileName().toString(), String.valueOf(s.getLine()),
						s.getReason().name(), oneLine(s.getDetail()), oneLine(lines[s.getLine() - 1])));
					skips.write('\n');
				}
				untranslated += result.getUntranslated();
			}
		}
		System.out.printf("%s: %d files, %d lines bundled, %d untranslated, skipped %s -> %s (%d KB)%n",
			language, files.size(), kept, untranslated, skipCounts, out.getFileName(), Files.size(out) / 1024);
		System.out.printf("%s: skipped lines listed in %s%n", language, report);
	}

	private static Writer gzipWriter(Path out) throws IOException
	{
		OutputStream gzip = new GZIPOutputStream(Files.newOutputStream(out))
		{
			{
				def.setLevel(Deflater.BEST_COMPRESSION);
			}
		};
		return new BufferedWriter(new OutputStreamWriter(gzip, StandardCharsets.UTF_8));
	}

	private static String oneLine(String text)
	{
		return text.replace('\t', ' ').replace('\n', ' ');
	}

	private static List<Path> list(Path dir, java.util.function.Predicate<Path> filter) throws IOException
	{
		try (Stream<Path> paths = Files.list(dir))
		{
			return paths.filter(filter).sorted().collect(Collectors.toList());
		}
	}
}

package com.runetongue.bundler;

import com.runetongue.glyph.GlyphColor;
import com.runetongue.glyph.GlyphRenderer;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;

/**
 * Build-time tool: draws the Plugin Hub icon (icon.png, at most 48x72) from the same glyph the
 * side panel button uses, "한" in orange, scaled up with nearest-neighbour so it stays a pixel font.
 */
public final class MakeIcon
{
	private static final int WIDTH = 48;
	private static final int HEIGHT = 72;
	private static final int SCALE = 4;

	private MakeIcon()
	{
	}

	public static void main(String[] args) throws IOException
	{
		BufferedImage glyph = GlyphRenderer.bundled().render('한', GlyphColor.ORANGE);
		BufferedImage icon = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		int w = glyph.getWidth() * SCALE;
		int h = glyph.getHeight() * SCALE;
		g.drawImage(glyph, (WIDTH - w) / 2, (HEIGHT - h) / 2, w, h, null);
		g.dispose();
		File out = new File(args[0]);
		ImageIO.write(icon, "png", out);
		System.out.println("wrote " + out + " (" + WIDTH + "x" + HEIGHT + ")");
	}
}

package com.runetongue;

import com.runetongue.glyph.GlyphIcons;
import com.runetongue.text.Scope;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.NPC;
import net.runelite.api.gameval.VarbitID;

/**
 * Translates game text that arrives as chat messages: examine text, game messages, level-up and
 * NPC lines echoed into the chatbox. Anything a player typed is never touched, and messages that
 * name other players (broadcasts, notifications, requests) are neither translated nor recorded.
 * Client thread only.
 */
@Singleton
class ChatTranslator
{
	private static final int OVERHEAD_YELLOW = 0xFFFF00;
	private static final Pattern LEADING_COLOR = Pattern.compile("^<col=([0-9a-fA-F]{6})>");

	private final Client client;
	private final GlyphIcons glyphs;
	private final GameTextLookup lookup;

	@Inject
	ChatTranslator(Client client, GlyphIcons glyphs, GameTextLookup lookup)
	{
		this.client = client;
		this.glyphs = glyphs;
		this.lookup = lookup;
	}

	/** Returns true if the message text was replaced. */
	boolean translate(MessageNode node)
	{
		Scope scope = scopeOf(node);
		String text = node.getValue();
		if (scope == null || text == null || text.contains("<img="))
		{
			return false;
		}
		String found = lookup.find(text, scope, !namesPlayers(node.getType()));
		if (found == null)
		{
			return false;
		}
		Matcher m = LEADING_COLOR.matcher(text);
		String tag = m.find() ? m.group() : "";
		int color = tag.isEmpty() ? defaultColor() : Integer.parseInt(m.group(1), 16);
		node.setValue(tag + glyphs.toChatText(found, color, false));
		return true;
	}

	/**
	 * Translates an NPC's overhead line, drawn yellow with a shadow like the game's. Players'
	 * overhead text is their own chat and is never touched.
	 */
	void translateOverhead(Actor actor, String text)
	{
		if (!(actor instanceof NPC) || text == null || text.contains("<img=") || actor.getName() == null)
		{
			return;
		}
		String name = GameTextLookup.plain(actor.getName());
		String found = lookup.find(text, Scope.of("dialogue", name, name), true);
		if (found != null)
		{
			actor.setOverheadText(glyphs.toChatText(found, OVERHEAD_YELLOW, true));
		}
	}

	/** Messages about other players: translated through templates, never recorded. */
	private static boolean namesPlayers(ChatMessageType type)
	{
		switch (type)
		{
			case BROADCAST:
			case CLAN_MESSAGE:
			case CLAN_GUEST_MESSAGE:
			case CLAN_GIM_MESSAGE:
			case FRIENDSCHATNOTIFICATION:
			case LOGINLOGOUTNOTIFICATION:
			case TRADEREQ:
			case CHALREQ_TRADE:
			case CHALREQ_FRIENDSCHAT:
			case CHALREQ_CLANCHAT:
			case PLAYERRELATED:
			case TENSECTIMEOUT:
			case CLAN_CREATION_INVITATION:
			case CLAN_GIM_FORM_GROUP:
			case CLAN_GIM_GROUP_WITH:
			case TRADE:
				return true;
			default:
				return false;
		}
	}

	/** Where the message's text is found in the data, or null for messages we leave alone. */
	private static Scope scopeOf(MessageNode node)
	{
		ChatMessageType type = node.getType();
		switch (type)
		{
			case ITEM_EXAMINE:
				return Scope.of("examine", "item", "");
			case NPC_EXAMINE:
				return Scope.of("examine", "npc", "");
			case OBJECT_EXAMINE:
				return Scope.of("examine", "object", "");
			case LEVELUPMESSAGE:
				return Scope.of("lvl_up_msg", "", "");
			case NPC_SAY:
			case DIALOG:
			{
				String name = node.getName() == null ? "" : GameTextLookup.plain(node.getName());
				return Scope.of("dialogue", name, name);
			}
			case GAMEMESSAGE:
			case ENGINE:
			case SPAM:
			case MESBOX:
			case WELCOME:
			case DIDYOUKNOW:
				return Scope.ANY;
			default:
				// System lines about other players, but never anything a player typed.
				return namesPlayers(type) ? Scope.ANY : null;
		}
	}

	/** Game messages are black on the opaque chatbox and white on the transparent one. */
	private int defaultColor()
	{
		boolean transparent = client.isResized() && client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY) == 1;
		return transparent ? 0xFFFFFF : 0x000000;
	}
}

package com.runetongue;

import com.runetongue.text.Scope;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Translates the chatbox dialogue: NPC lines, player lines, options, the NPC name, the
 * "Click here to continue" prompt, and the message, item, picture and level-up boxes. Runs every
 * frame on the client thread but only looks at those few widgets; {@link WidgetTexts} does the
 * rest.
 */
@Singleton
class DialogueTranslator
{
	private static final String DIALOGUE = "dialogue";
	private static final Scope FIXED = Scope.of(DIALOGUE, "manual", "");
	private static final Scope BOX = Scope.of(DIALOGUE, "", "");
	private static final Scope LEVEL_UP = Scope.of("lvl_up_msg", "", "");
	private static final String PLAYER = "Player";

	private final Client client;
	private final WidgetTexts texts;
	/** The NPC in the current conversation, in English; player lines and options are looked up under it. */
	private String npc = "";

	@Inject
	DialogueTranslator(Client client, WidgetTexts texts)
	{
		this.client = client;
		this.texts = texts;
	}

	void update()
	{
		String name = handle(InterfaceID.ChatLeft.NAME, Scope.of("name", "npc", ""), false);
		if (name != null)
		{
			npc = GameTextLookup.plain(name);
		}
		handle(InterfaceID.ChatLeft.TEXT, Scope.of(DIALOGUE, npc, npc), true);
		handle(InterfaceID.ChatLeft.CONTINUE, FIXED, false);
		handle(InterfaceID.ChatRight.TEXT, Scope.of(DIALOGUE, npc, PLAYER), true);
		handle(InterfaceID.ChatRight.CONTINUE, FIXED, false);

		Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		Widget[] children = options == null || options.isHidden() ? null : options.getDynamicChildren();
		if (children != null)
		{
			for (int i = 0; i < children.length; i++)
			{
				texts.handle(children[i], key(InterfaceID.Chatmenu.OPTIONS, i),
					WidgetTexts.Request.dialogue(i == 0 ? FIXED : Scope.of(DIALOGUE, npc, PLAYER), false));
			}
		}

		// Boxes without a speaker: plain and titled messages, item and picture boxes, level-ups.
		handle(InterfaceID.Messagebox.TEXT, BOX, true);
		handle(InterfaceID.Messagebox.CONTINUE, FIXED, false);
		handle(InterfaceID.MessageboxTitled.TITLE, BOX, false);
		handle(InterfaceID.MessageboxTitled.TEXT, BOX, true);
		handle(InterfaceID.MessageboxTitled.CONTINUE, FIXED, false);
		handle(InterfaceID.Objectbox.TEXT, BOX, true);
		handle(InterfaceID.ObjectboxDouble.TEXT, BOX, true);
		handle(InterfaceID.Graphicbox.TEXT, BOX, true);
		handle(InterfaceID.LevelupDisplay.TEXT1, LEVEL_UP, true);
		handle(InterfaceID.LevelupDisplay.TEXT2, LEVEL_UP, true);
		handle(InterfaceID.LevelupDisplay.CONTINUE, FIXED, false);
	}

	void reset()
	{
		npc = "";
	}

	private String handle(int widgetId, Scope scope, boolean wrap)
	{
		return texts.handle(client.getWidget(widgetId), key(widgetId, 0), WidgetTexts.Request.dialogue(scope, wrap));
	}

	/** Widget ids fill 32 bits; the low 16 bits of the key leave room for a dynamic child's index. */
	static long key(int widgetId, int index)
	{
		return ((long) widgetId << 16) | index;
	}
}

package com.runetongue;

import com.runetongue.text.Normalizer;
import com.runetongue.text.TextLookup;
import com.runetongue.text.Scope;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.util.Text;

/**
 * Looks up one piece of game text as the game shows it: tags are dropped, the player's own name
 * is looked up as {@code [player name]}, numbers are put back into the translation, and a miss is
 * recorded for the missing-text file. Shared by every part of the plugin that replaces text.
 * Client thread only.
 */
@Singleton
class GameTextLookup
{
	private static final char NBSP = '\u00A0';
	/** Spaces game or wiki text may use instead of a plain one (RuneLingual's replaceSpecialSpaces). */
	private static final Pattern SPECIAL_SPACES = Pattern.compile("[\\t\\u00A0\\u2000-\\u200A\\u202F\\u205F\\u3000]");
	private static final Pattern ZERO_WIDTH = Pattern.compile("[\\u200B-\\u200D\\uFEFF]");

	private final Client client;
	private final TranslationStore store;
	private final MissingTexts missing;

	@Inject
	GameTextLookup(Client client, TranslationStore store, MissingTexts missing)
	{
		this.client = client;
		this.store = store;
		this.missing = missing;
	}

	boolean isReady()
	{
		return store.isLoaded();
	}

	/** The translation of {@code shown}, or null. {@code record} is false for text that may hold other players' words. */
	String find(String shown, Scope scope, boolean record)
	{
		return lookUp(plain(shown), scope, record);
	}

	/**
	 * Like {@link #find} but for interface text, whose data keeps color tags (as {@code <colNum0>})
	 * and, for widgets whose lines are laid out by hand, {@code <br>}. The translation comes back
	 * with the same tags.
	 */
	String findKeepingTags(String shown, Scope scope, boolean keepBr, boolean record)
	{
		String english = spaces(shown);
		if (!keepBr)
		{
			english = english.replace(" <br>", " ").replace("<br> ", " ").replace("<br>", " ");
		}
		return lookUp(english.trim(), scope, record);
	}

	private String lookUp(String english, Scope scope, boolean record)
	{
		if (english.isEmpty())
		{
			return null;
		}
		String player = playerName();
		if (player != null)
		{
			english = english.replace(player, Normalizer.PLAYER_NAME);
		}
		String text = TextLookup.translate(store.get(), english, scope);
		if (text == null)
		{
			if (record && store.isLoaded())
			{
				missing.record(Normalizer.normalizeSource(english).getKey(), scope);
			}
			return null;
		}
		return player == null ? text : text.replace(Normalizer.PLAYER_NAME, player);
	}

	/** Game text without tags; a {@code <br>} the game put in place of a space becomes a space again. */
	static String plain(String shown)
	{
		return spaces(Text.removeTags(shown.replaceAll("(?<=\\S)<br>(?=\\S)", " "))).trim();
	}

	private static String spaces(String text)
	{
		return ZERO_WIDTH.matcher(SPECIAL_SPACES.matcher(text).replaceAll(" ")).replaceAll("");
	}

	private String playerName()
	{
		Player local = client.getLocalPlayer();
		String name = local == null ? null : local.getName();
		return name == null || name.isEmpty() ? null : name.replace(NBSP, ' ');
	}
}

package com.runetongue;

import com.runetongue.WidgetTexts.Layout;
import com.runetongue.text.Scope;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;

/**
 * Per-widget rules for interface text, ported from RuneLingual's {@code Ids} and
 * {@code WidgetCapture} (BSD 2-Clause, Copyright (c) 2024, Y. S. Jack): where in the data a
 * widget's text is, how its lines are laid out, and which widgets show other players' names.
 */
final class InterfaceRules
{
	private InterfaceRules()
	{
	}

	static final Scope GENERAL_UI = Scope.of("interface", "generalUI", "");
	private static final Scope MAIN_TABS = Scope.of("interface", "mainTabs", "");

	/** Widgets whose subtree sets the scope for the text inside it. */
	private static final Map<Integer, Scope> CONTEXTS = Map.ofEntries(
		Map.entry(InterfaceID.Toplevel.SIDE_PANELS, MAIN_TABS),
		Map.entry(InterfaceID.ToplevelPreEoc.SIDE_PANELS, MAIN_TABS),
		Map.entry(InterfaceID.ToplevelOsrsStretch.SIDE_PANELS, MAIN_TABS),
		Map.entry(InterfaceID.CombatInterface.UNIVERSE, tab("combatOptionsTab")),
		Map.entry(InterfaceID.Stats.UNIVERSE, tab("skillsTab")),
		Map.entry(InterfaceID.AccountSummarySidepanel.SUMMARY_CONTENTS, tab("characterSummaryTab")),
		Map.entry(InterfaceID.Questlist.UNIVERSE, tab("questListTab")),
		Map.entry(InterfaceID.AreaTask.TASKBOX, tab("achievementDiaryTab")),
		Map.entry(InterfaceID.Prayerbook.UNIVERSE, tab("prayerTab")),
		Map.entry(InterfaceID.MagicSpellbook.UNIVERSE, tab("spellBookTab")),
		Map.entry(InterfaceID.SideChannelsLarge.UNIVERSE, tab("groupTab")),
		Map.entry(InterfaceID.SideChannels.UNIVERSE, tab("groupTab")),
		Map.entry(InterfaceID.PvpArenaSidepanel.UNIVERSE, tab("groupTab")),
		Map.entry(InterfaceID.Friends.UNIVERSE, tab("friendsTab")),
		Map.entry(InterfaceID.Ignore.UNIVERSE, tab("ignoreTab")),
		Map.entry(InterfaceID.Account.CONTENT, tab("accountManagementTab")),
		Map.entry(InterfaceID.SettingsSide.UNIVERSE, tab("settingsTab")),
		Map.entry(InterfaceID.Emote.UNIVERSE, tab("emotesTab")),
		Map.entry(InterfaceID.Music.UNIVERSE, tab("musicTab")),
		Map.entry(InterfaceID.Logout.UNIVERSE, tab("logoutTab")),
		Map.entry(InterfaceID.Worldswitcher.UNIVERSE, tab("worldSwitcherTab")),
		Map.entry(InterfaceID.SkillGuide.INFINITY, Scope.of("interface", "generalUI", "skillGuide")),
		Map.entry(InterfaceID.Chatbox.CONTROLS, Scope.of("interface", "chatButtons", "")),
		Map.entry(InterfaceID.WelcomeScreen.CONTENT, Scope.of("interface", "loginScreen", "")),
		Map.entry(InterfaceID.CaOverview.INFINITY, Scope.of("interface", "combAchvmt", "")),
		Map.entry(InterfaceID.CaTasks.INFINITY, Scope.of("interface", "combAchvmt", "")),
		Map.entry(InterfaceID.CaBosses.INFINITY, Scope.of("interface", "combAchvmt", "")),
		Map.entry(InterfaceID.CaRewards.INFINITY, Scope.of("interface", "combAchvmt", "")),
		Map.entry(InterfaceID.CaBoss.INFINITY, Scope.of("interface", "combAchvmt", "")),
		Map.entry(InterfaceID.CaTasks.DROPDOWN_BOX, Scope.of("interface", "combAchvmt", "")));

	/** Text widgets that show a name, looked up as one (without color tags). */
	private static final Map<Integer, Scope> NAMES = Map.of(
		InterfaceID.CombatInterface.TITLE, Scope.of("name", "item", ""),
		InterfaceID.CaBosses.BOSSES_NAME, Scope.of("name", "npc", ""),
		InterfaceID.CaBoss.BOSS_NAME, Scope.of("name", "npc", ""),
		InterfaceID.Questlist.LIST, Scope.of("manual", "quest", ""));

	/** Hover displays with several values in one text: each line on its own. */
	private static final Set<Integer> SPLIT_AT_BR = Set.of(InterfaceID.Stats.TOOLTIP, InterfaceID.XpDrops.TOOLTIP);

	/** Text whose data keeps the game's line breaks (descriptions, buttons with two lines). */
	private static final Set<Integer> KEEP_BR = Set.of(
		InterfaceID.Prayerbook.TOOLTIP, InterfaceID.MagicSpellbook.TOOLTIP,
		InterfaceID.Friends.UNIVERSE_TEXT4, InterfaceID.Friends.UNIVERSE_TEXT6,
		InterfaceID.SettingsSide.TOOLTIP, InterfaceID.Emote.TOOLTIP,
		InterfaceID.Worldswitcher.TOOLTIP, InterfaceID.Worldswitcher.INFO,
		InterfaceID.PohOptions.TOOLTIP, InterfaceID.PohOptions.ROOT_TEXT2, InterfaceID.PohOptions.ROOT_TEXT3,
		InterfaceID.Prayerbook.FILTERBUTTON, InterfaceID.MagicSpellbook.FILTERBUTTON,
		InterfaceID.GimSidepanel.INVITE, InterfaceID.GimSidepanel.SETTINGS,
		InterfaceID.ChatchannelCurrent.CHANNELNAME, InterfaceID.ChatchannelCurrent.CHANNELOWNER,
		InterfaceID.ChatchannelCurrent.JOINLEAVE, InterfaceID.ChatchannelCurrent.SETUP,
		InterfaceID.ClansSidepanel.HEADER, InterfaceID.ClansSidepanel.CHAT, InterfaceID.ClansSidepanel.INFO,
		InterfaceID.ClansGuestSidepanel.HEADER, InterfaceID.ClansGuestSidepanel.CHAT,
		InterfaceID.ClansGuestSidepanel.INFO, InterfaceID.ClansGuestSidepanel.SEARCH,
		InterfaceID.Friends.LIST, InterfaceID.Account.NAME_TEXT);

	/** Widgets given a fixed width and left on their own lines (achievement diary area names). */
	private static final Map<Integer, Integer> FIXED_WIDTH = Map.of(InterfaceID.AreaTask.TASKBOX, 110);

	/** Subtrees never translated: chat lines, the player's name, clocks, search boxes. */
	private static final Set<Integer> SKIPPED_WIDGETS = Set.of(
		InterfaceID.Chatbox.CHATDISPLAY, InterfaceID.Chatbox.LINE499, InterfaceID.Chatbox.SCROLLAREA,
		InterfaceID.AccountSummarySidepanel.SUMMARY_PLAYER_NAME, InterfaceID.Ignore.LIST_CONTAINER,
		InterfaceID.GimSidepanel.TITLE, InterfaceID.SideChannelsLarge.CLOCK, InterfaceID.SideChannels.CLOCK,
		InterfaceID.Settings.SEARCH_TEXT, InterfaceID.CaBosses.SEARCH_TEXT, InterfaceID.ToplevelDisplay.LAYERS);

	/** Interfaces translated elsewhere ({@link DialogueTranslator}) or not at all (private chat). */
	private static final Set<Integer> SKIPPED_GROUPS = Set.of(
		InterfaceID.PM_CHAT,
		InterfaceID.CHAT_LEFT, InterfaceID.CHAT_RIGHT, InterfaceID.CHAT_BOTH, InterfaceID.CHATMENU,
		InterfaceID.MESSAGEBOX, InterfaceID.MESSAGEBOX_TITLED, InterfaceID.MESSAGEBOX_URL,
		InterfaceID.OBJECTBOX, InterfaceID.OBJECTBOX_DOUBLE, InterfaceID.GRAPHICBOX, InterfaceID.LEVELUP_DISPLAY);

	/** Interfaces with other players' names in them: translated, but unknown text is not recorded. */
	private static final Set<Integer> UNRECORDED_GROUPS = Set.of(
		InterfaceID.FRIENDS, InterfaceID.IGNORE, InterfaceID.CHATCHANNEL_CURRENT, InterfaceID.CHATCHANNEL_SETUP,
		InterfaceID.CLANS_SIDEPANEL, InterfaceID.CLANS_GUEST_SIDEPANEL, InterfaceID.CLANS_MEMBERS,
		InterfaceID.GIM_SIDEPANEL, InterfaceID.TRADEMAIN, InterfaceID.TRADESIDE, InterfaceID.TRADECONFIRM,
		InterfaceID.HISCORES, InterfaceID.ACCOUNT, InterfaceID.ACCOUNT_SUMMARY_SIDEPANEL, InterfaceID.GROUPING);

	private static final Set<Integer> CHAT_BUTTON_NAMES = Set.of(
		InterfaceID.Chatbox.CHAT_GAME_TEXT1, InterfaceID.Chatbox.CHAT_PUBLIC_TEXT1, InterfaceID.Chatbox.CHAT_PRIVATE_TEXT1,
		InterfaceID.Chatbox.CHAT_FRIENDSCHAT_TEXT1, InterfaceID.Chatbox.CHAT_CLAN_TEXT1, InterfaceID.Chatbox.CHAT_TRADE_TEXT);
	private static final Set<Integer> CHAT_BUTTON_FILTERS = Set.of(
		InterfaceID.Chatbox.CHAT_GAME_FILTER, InterfaceID.Chatbox.CHAT_PUBLIC_FILTER, InterfaceID.Chatbox.CHAT_PRIVATE_FILTER,
		InterfaceID.Chatbox.CHAT_FRIENDSCHAT_FILTER, InterfaceID.Chatbox.CHAT_CLAN_FILTER, InterfaceID.Chatbox.CHAT_TRADE_FILTER);

	/** The chatbox itself (lines, input) is skipped; only its tab buttons are translated. */
	static boolean isChatbox(int widgetId)
	{
		return widgetId >>> 16 == InterfaceID.CHATBOX;
	}

	static Scope context(int widgetId, Scope inherited)
	{
		return CONTEXTS.getOrDefault(widgetId, inherited);
	}

	static boolean skipsSubtree(Widget widget)
	{
		return SKIPPED_WIDGETS.contains(widget.getId()) || SKIPPED_GROUPS.contains(widget.getId() >>> 16);
	}

	/** Text widgets that list other players, told apart from the UI text around them as RuneLingual did. */
	static boolean isPlayerText(Widget widget, boolean inFriendsChat)
	{
		int id = widget.getId();
		int color = widget.getTextColor();
		boolean left = widget.getXTextAlignment() == WidgetTextAlignment.LEFT;
		return (id == InterfaceID.Friends.LIST && left)
			|| (id == InterfaceID.GimSidepanel.MEMBERS && left && color == 0xffffff)
			|| (id == InterfaceID.ChatchannelCurrent.LIST && color == 0xffffff)
			|| ((id == InterfaceID.ChatchannelCurrent.CHANNELNAME || id == InterfaceID.ChatchannelCurrent.CHANNELOWNER) && inFriendsChat)
			|| ((id == InterfaceID.ClansSidepanel.HEADER || id == InterfaceID.ClansGuestSidepanel.HEADER) && color == 0xe6981f)
			|| ((id == InterfaceID.ClansSidepanel.PLAYERLIST || id == InterfaceID.ClansGuestSidepanel.PLAYERLIST) && color == 0xffffff)
			|| (id == InterfaceID.PvpArenaSidepanel.PLAYERLIST && (color == 0xffffff || color == 0x9f9f9f))
			|| (id == InterfaceID.Grouping.PLAYERLIST && color == 0xffffff)
			|| id == InterfaceID.Chatbox.SCROLLAREA;
	}

	/** Widgets whose menus are about another player: chat lines, friends, clan and channel lists. */
	static boolean listsPlayers(Widget widget)
	{
		int group = widget.getId() >>> 16;
		return group == InterfaceID.CHATBOX || group == InterfaceID.PM_CHAT || UNRECORDED_GROUPS.contains(group)
			|| isPlayerText(widget, false);
	}

	static WidgetTexts.Request request(Widget widget, Scope context, boolean record)
	{
		int id = widget.getId();
		boolean recordHere = record && !UNRECORDED_GROUPS.contains(id >>> 16);
		Scope name = NAMES.get(id);
		if (name != null && !(id == InterfaceID.CombatInterface.TITLE && "Unarmed".equals(widget.getText())))
		{
			return new WidgetTexts.Request(name, Layout.AS_IS, false, recordHere, true, 0);
		}
		Layout layout = SPLIT_AT_BR.contains(id) ? Layout.SPLIT_AT_BR
			: KEEP_BR.contains(id) ? Layout.KEEP_BR
			: FIXED_WIDTH.containsKey(id) ? Layout.AS_IS
			: Layout.WRAP;
		return new WidgetTexts.Request(context, layout, true, recordHere, true, FIXED_WIDTH.getOrDefault(id, 0));
	}

	/** Korean chat tab names fit only side by side with the filter: name left, filter right. */
	static void alignChatButton(Widget widget)
	{
		if (CHAT_BUTTON_NAMES.contains(widget.getId()))
		{
			widget.setXTextAlignment(WidgetTextAlignment.LEFT);
		}
		else if (CHAT_BUTTON_FILTERS.contains(widget.getId()))
		{
			widget.setXTextAlignment(WidgetTextAlignment.RIGHT);
		}
	}

	private static Scope tab(String source)
	{
		return Scope.of("interface", "mainTabs", source);
	}
}

package com.runetongue;

import com.runetongue.text.Scope;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

/**
 * Translates the text of every visible interface: side tabs, skill guides, settings, lists and
 * hover boxes. Walks the visible widget tree each frame, works out each text widget's scope from
 * the interfaces it sits in, and hands it to {@link WidgetTexts}, which only looks a text up when
 * it changes. The per-widget rules come from RuneLingual ({@link InterfaceRules}). Client thread
 * only.
 */
@Slf4j
@Singleton
class InterfaceTranslator
{
	/** Player names are at most 12 characters; shorter unknown text is not recorded as missing. */
	private static final int SHORTEST_RECORDED = 13;
	private static final int STATS_EVERY = 3000;

	private final Client client;
	private final WidgetTexts texts;
	private long frames;
	private long totalNanos;
	private long maxNanos;
	private int lastVisited;

	@Inject
	InterfaceTranslator(Client client, WidgetTexts texts)
	{
		this.client = client;
		this.texts = texts;
	}

	void update()
	{
		Widget[] roots = client.getWidgetRoots();
		if (roots == null)
		{
			return;
		}
		long start = System.nanoTime();
		lastVisited = 0;
		boolean inFriendsChat = client.getFriendsChatManager() != null;
		for (Widget root : roots)
		{
			visit(root, DialogueTranslator.key(root.getId(), 0), InterfaceRules.GENERAL_UI, inFriendsChat);
		}
		measure(System.nanoTime() - start);
	}

	private void visit(Widget widget, long key, Scope inherited, boolean inFriendsChat)
	{
		if (widget == null || widget.isSelfHidden() || InterfaceRules.skipsSubtree(widget))
		{
			return;
		}
		lastVisited++;
		Scope context = InterfaceRules.context(widget.getId(), inherited);
		if (widget.getType() == WidgetType.TEXT && widget.getFontId() != -1)
		{
			translate(widget, key, context, inFriendsChat);
		}
		Widget[] dynamic = widget.getDynamicChildren();
		if (dynamic != null)
		{
			for (int i = 0; i < dynamic.length; i++)
			{
				visit(dynamic[i], DialogueTranslator.key(widget.getId(), i + 1), context, inFriendsChat);
			}
		}
		visitAll(widget.getStaticChildren(), context, inFriendsChat);
		visitAll(widget.getNestedChildren(), context, inFriendsChat);
	}

	private void visitAll(Widget[] children, Scope context, boolean inFriendsChat)
	{
		if (children != null)
		{
			for (Widget child : children)
			{
				visit(child, DialogueTranslator.key(child.getId(), 0), context, inFriendsChat);
			}
		}
	}

	private void translate(Widget widget, long key, Scope context, boolean inFriendsChat)
	{
		String text = widget.getText();
		if (text == null || !hasLetter(text) || InterfaceRules.isPlayerText(widget, inFriendsChat))
		{
			return;
		}
		boolean chatbox = InterfaceRules.isChatbox(widget.getId());
		if (chatbox && !"chatButtons".equals(context.getSubCategory()))
		{
			return;
		}
		boolean record = GameTextLookup.plain(text).length() >= SHORTEST_RECORDED;
		texts.handle(widget, key, InterfaceRules.request(widget, context, record));
		if (chatbox && widget.getText().contains("<img="))
		{
			InterfaceRules.alignChatButton(widget);
		}
	}

	private static boolean hasLetter(String text)
	{
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (c == '<')
			{
				int end = text.indexOf('>', i);
				if (end < 0)
				{
					return false;
				}
				i = end;
			}
			else if (Character.isLetter(c))
			{
				return true;
			}
		}
		return false;
	}

	private void measure(long nanos)
	{
		frames++;
		totalNanos += nanos;
		maxNanos = Math.max(maxNanos, nanos);
		if (frames == STATS_EVERY)
		{
			log.debug("interface walk: {} widgets, avg {} us, max {} us over {} frames",
				lastVisited, totalNanos / frames / 1000, maxNanos / 1000, frames);
			frames = 0;
			totalNanos = 0;
			maxNanos = 0;
		}
	}
}

package com.runetongue;

import lombok.AllArgsConstructor;
