package com.runetongue;

import com.runetongue.text.ParseResult;
import com.runetongue.text.SkipReason;
import java.util.List;
import lombok.Value;

@Value
public class LoadReport
{
	@Value
	public static class FileReport
	{
		String fileName;
		ParseResult result;

		public int loadedLines()
		{
			return (int) result.getEntries().stream().map(e -> e.getLine()).distinct().count();
		}

		public long skippedLines()
		{
			return result.getSkipped().stream().filter(s -> s.getReason() != SkipReason.OVERRIDDEN).count();
		}
	}

	Language language;
	String folder;
	List<FileReport> files;
	int bundledEntries;
	String error;

	public int loadedLines()
	{
		return files.stream().mapToInt(FileReport::loadedLines).sum();
	}

	public long skippedLines()
	{
		return files.stream().mapToLong(FileReport::skippedLines).sum();
	}

	public int untranslatedLines()
	{
		return files.stream().mapToInt(f -> f.getResult().getUntranslated()).sum();
	}

	/** One line shared by the chat message and the side panel. */
	public String summary()
	{
		if (error != null)
		{
			return language.ui("번역 폴더를 읽지 못했어요: ", "Could not read the translation folder: ") + error;
		}
		return String.format(language.ui("%s 파일 %d개, %d줄 불러옴, %d줄 건너뜀, 미번역 %d줄 (내장 번역 %d개)",
			"%s: %d files, %d lines loaded, %d skipped, %d untranslated (%d bundled)"),
			language.getCode(), files.size(), loadedLines(), skippedLines(), untranslatedLines(), bundledEntries);
	}

	/** "6번째 줄: 이유" or "line 6: reason". */
	public String skippedLine(ParseResult.Skipped s)
	{
		return language.ui(s.getLine() + "번째 줄: " + s.getReason().getMessage(),
			"line " + s.getLine() + ": " + s.getReason().getEnglishMessage());
	}
}

package com.runetongue;

import com.runetongue.glyph.GlyphIcons;
import com.runetongue.text.Scope;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.client.util.Text;

/**
 * Translates right-click menu options and the names in their targets. Menu text is replaced just
 * before each frame is drawn, after every plugin has added and sorted entries by their English
 * text, and put back when an entry is clicked so other plugins still see English. Results are
 * cached, so a frame costs a few map lookups. Client thread only.
 */
@Slf4j
@Singleton
class MenuTranslator
{
	private static final int CACHE_SIZE = 4096;
	private static final int WHITE = 0xFFFFFF;
	/** A target is a run of {@code <col=rrggbb>text} pieces, e.g. a name followed by its level. */
	private static final Pattern PIECE = Pattern.compile("(<col=([0-9a-fA-F]{1,6})>)?([^<]+)|(<[^>]*>)");
	private static final Pattern LEVEL = Pattern.compile("\\s*\\(level-\\d+\\)\\s*");
	private static final Pattern LEVEL_ANYWHERE = Pattern.compile("\\(level-\\d+\\)");
	private static final Scope LEVEL_SCOPE = Scope.of("name", "level", "");
	private static final String MEMBERS = " (Members)";
	private static final Scope MEMBERS_SCOPE = Scope.of("actions", "item", "");

	private final Client client;
	private final GlyphIcons glyphs;
	private final GameTextLookup lookup;
	/** Translated text by original, for options and targets alike; also tells our own output apart. */
	private final Map<String, String> translated = lru();
	private final Map<String, String> originals = lru();

	@Inject
	MenuTranslator(Client client, GlyphIcons glyphs, GameTextLookup lookup)
	{
		this.client = client;
		this.glyphs = glyphs;
		this.lookup = lookup;
	}

	void update()
	{
		if (!lookup.isReady())
		{
			return;
		}
		for (MenuEntry entry : client.getMenu().getMenuEntries())
		{
			translate(entry);
			Menu sub = entry.getSubMenu();
			if (sub != null)
			{
				for (MenuEntry subEntry : sub.getMenuEntries())
				{
					translate(subEntry);
				}
			}
		}
	}

	private void translate(MenuEntry entry)
	{
		String option = entry.getOption();
		String target = entry.getTarget();
		if (originals.containsKey(option) || originals.containsKey(target))
		{
			return;
		}
		// Added by a RuneLite plugin: the option may be translated, but it is not game text to record.
		boolean byPlugin = entry.getType().name().startsWith("RUNELITE");
		Kind kind = Kind.of(entry);
		boolean player = kind == Kind.PLAYER || byPlugin
			|| (entry.getType() == MenuAction.WALK && LEVEL_ANYWHERE.matcher(target).find())
			|| (entry.getWidget() != null && InterfaceRules.listsPlayers(entry.getWidget()));
		boolean record = !player;
		String name = player ? "" : Text.removeTags(LEVEL.matcher(target).replaceAll("")).trim();
		String newOption = cached(kind.ordinal() + "|" + player + "|" + name + "|" + option, option,
			() -> option(option, kind, name, record));
		String newTarget = cached(kind.ordinal() + "|" + player + "|" + target, target, () -> target(target, kind, player, record));
		if (!newOption.equals(option))
		{
			entry.setOption(newOption);
		}
		if (!newTarget.equals(target))
		{
			entry.setTarget(newTarget);
		}
	}

	/** The English of an option or target this translated, or null if it is not a translation. */
	String originalOf(String text)
	{
		return originals.get(text);
	}

	/** Puts the English back on a clicked entry before other plugins read it. */
	void restore(MenuEntry entry)
	{
		String option = originals.get(entry.getOption());
		if (option != null)
		{
			entry.setOption(option);
		}
		String target = originals.get(entry.getTarget());
		if (target != null)
		{
			entry.setTarget(target);
		}
	}

	void reset()
	{
		translated.clear();
		originals.clear();
	}

	private String cached(String key, String original, java.util.function.Supplier<String> translate)
	{
		String result = translated.get(key);
		if (result == null)
		{
			result = translate.get();
			log.debug("menu {} -> {}", key, result);
			translated.put(key, result);
			if (!result.equals(original))
			{
				originals.put(result, original);
			}
		}
		return result;
	}

	/** Options keep their color tags in the data ("<colNum0>Public:</col> Show friends"). */
	private String option(String option, Kind kind, String targetName, boolean record)
	{
		String found = lookup.findKeepingTags(option, Scope.of(kind.category, kind.subCategory, targetName), false, record);
		return found == null ? option : glyphs.toChatText(found, WHITE, false);
	}

	/**
	 * Translates each name piece of the target, keeping its color. A level suffix gets the word
	 * "level" translated; a player's name, and the player after "Use X ->", stay as they are. The
	 * piece before " -> " is the item being used.
	 */
	private String target(String target, Kind kind, boolean player, boolean record)
	{
		StringBuilder out = new StringBuilder();
		boolean changed = false;
		boolean hasArrow = target.contains("->");
		boolean afterArrow = false;
		Matcher m = PIECE.matcher(target);
		while (m.find())
		{
			if (m.group(4) != null)
			{
				out.append(m.group(4));
				continue;
			}
			String tag = m.group(1) == null ? "" : m.group(1);
			String text = m.group(3);
			int color = m.group(2) == null ? WHITE : Integer.parseInt(m.group(2), 16);
			String translated = null;
			if (text.contains("->"))
			{
				afterArrow = true;
			}
			else if (LEVEL.matcher(text).matches())
			{
				translated = level(text, color);
			}
			else if (!(player && (!hasArrow || afterArrow)) && !text.trim().isEmpty())
			{
				String sub = hasArrow && !afterArrow ? "item" : kind.nameSubCategory;
				translated = name(text, sub, color, record);
			}
			changed |= translated != null;
			out.append(tag).append(translated != null ? translated : text);
		}
		return changed ? out.toString() : target;
	}

	/** "  (level-15)" with the word "level" translated; the digits and spacing stay. */
	private String level(String text, int color)
	{
		String word = lookup.find("level", LEVEL_SCOPE, false);
		return word == null ? null : glyphs.toChatText(text.replace("level", word), color, false);
	}

	/** A name, keeping the spaces around it; "Name (Members)" is translated in two parts. */
	private String name(String text, String subCategory, int color, boolean record)
	{
		String name = text.trim();
		String suffix = "";
		if (name.endsWith(MEMBERS) && name.length() > MEMBERS.length())
		{
			String members = lookup.find(MEMBERS.trim(), MEMBERS_SCOPE, false);
			if (members != null)
			{
				suffix = " " + members;
				name = name.substring(0, name.length() - MEMBERS.length());
			}
		}
		String found = lookup.find(name, Scope.of("name", subCategory, ""), record);
		if (found == null)
		{
			return null;
		}
		String lead = text.substring(0, text.indexOf(text.trim()));
		String trail = text.substring(text.indexOf(text.trim()) + text.trim().length());
		return lead + glyphs.toChatText(found + suffix, color, false) + trail;
	}

	private static <V> Map<String, V> lru()
	{
		return new LinkedHashMap<String, V>(256, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, V> eldest)
			{
				return size() > CACHE_SIZE;
			}
		};
	}

	/** What a menu entry acts on, and where its option and target are found in the data. */
	private enum Kind
	{
		NPC("actions", "npc", "npc"),
		OBJECT("actions", "object", "object"),
		GROUND_ITEM("actions", "item", "item"),
		INVENTORY_ITEM("inventoryActions", "item", "item"),
		PLAYER("actions", "player", "player"),
		FIXED("actions", "manual", "menu"),
		OTHER("actions", "menu", "menu");

		final String category;
		final String subCategory;
		final String nameSubCategory;

		Kind(String category, String subCategory, String nameSubCategory)
		{
			this.category = category;
			this.subCategory = subCategory;
			this.nameSubCategory = nameSubCategory;
		}

		static Kind of(MenuEntry entry)
		{
			MenuAction type = entry.getType();
			if (entry.getNpc() != null)
			{
				return NPC;
			}
			if (entry.getPlayer() != null)
			{
				return PLAYER;
			}
			switch (type)
			{
				case GAME_OBJECT_FIRST_OPTION:
				case GAME_OBJECT_SECOND_OPTION:
				case GAME_OBJECT_THIRD_OPTION:
				case GAME_OBJECT_FOURTH_OPTION:
				case GAME_OBJECT_FIFTH_OPTION:
				case EXAMINE_OBJECT:
				case WIDGET_TARGET_ON_GAME_OBJECT:
					return OBJECT;
				case GROUND_ITEM_FIRST_OPTION:
				case GROUND_ITEM_SECOND_OPTION:
				case GROUND_ITEM_THIRD_OPTION:
				case GROUND_ITEM_FOURTH_OPTION:
				case GROUND_ITEM_FIFTH_OPTION:
				case EXAMINE_ITEM_GROUND:
				case WIDGET_TARGET_ON_GROUND_ITEM:
					return GROUND_ITEM;
				case WALK:
				case CANCEL:
					return FIXED;
				default:
					return entry.getItemId() > 0 ? INVENTORY_ITEM : OTHER;
			}
		}
	}
}

package com.runetongue;

import com.runetongue.text.Scope;
import com.runetongue.text.TextLookup;
import com.runetongue.text.Translations;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.IntConsumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Collects text the plugin could not translate into {@code missing/<lang>/missing.tsv}, in the
 * user translation file format with the translation column empty, so a filled-in copy can go
 * straight into the translations folder (CONTEXT.md 3.5). Each English text and scope is written
 * once, across sessions. Only game text is recorded, never chat, and the player's name is already
 * replaced with {@code [player name]} by the caller. Disk access happens on the executor.
 */
@Slf4j
@Singleton
class MissingTexts
{
	static final String FILE_NAME = "missing.tsv";
	private static final String HEADER = "english\ttranslation\tcategory\tsub_category\tsource\n";

	/** One language's file; replaced as a whole when the language changes. */
	private static final class Session
	{
		final Set<String> seen = ConcurrentHashMap.newKeySet();
		volatile Filepath file;
	}

	private final ScheduledExecutorService executor;
	private volatile Session session;

	@Inject
	MissingTexts(ScheduledExecutorService executor)
	{
		this.executor = executor;
	}

	void start(Callable<Filepath> folder)
	{
		Session s = new Session();
		session = s;
		executor.execute(() ->
		{
			try
			{
				Filepath dir = folder.call();
				dir.createDirectories();
				Filepath file = dir.join(FILE_NAME);
				if (file.exists())
				{
					try (BufferedReader in = file.openBufferedReader())
					{
						in.lines().skip(1).map(MissingTexts::keyOfLine).forEach(s.seen::add);
					}
				}
				s.file = file;
				log.debug("collecting missing text in {} ({} already listed)", file, s.seen.size());
			}
			catch (Exception e)
			{
				log.warn("could not open the missing text file", e);
			}
		});
	}

	void stop()
	{
		session = null;
	}

	/**
	 * Drops the lines that {@code translations} now translates, e.g. after a translated copy was
	 * put in the translations folder, and reports how many lines are left. Runs on the executor,
	 * after any writes already queued, since RuneLite's executor has a single thread.
	 */
	void prune(Translations translations, IntConsumer remaining)
	{
		Session s = session;
		if (s == null)
		{
			return;
		}
		executor.execute(() ->
		{
			try
			{
				if (s.file == null || !s.file.exists())
				{
					remaining.accept(0);
					return;
				}
				List<String> kept = new ArrayList<>();
				int dropped = 0;
				try (BufferedReader in = s.file.openBufferedReader())
				{
					for (String line : (Iterable<String>) in.lines().skip(1)::iterator)
					{
						if (line.isEmpty())
						{
							continue;
						}
						if (isTranslated(translations, line))
						{
							dropped++;
						}
						else
						{
							kept.add(line);
						}
					}
				}
				if (dropped > 0)
				{
					StringBuilder out = new StringBuilder(HEADER);
					kept.forEach(line -> out.append(line).append('\n'));
					s.file.write(out.toString().getBytes(StandardCharsets.UTF_8));
					log.debug("dropped {} now translated lines from {}", dropped, s.file);
				}
				remaining.accept(kept.size());
			}
			catch (IOException e)
			{
				log.warn("could not tidy the missing text file", e);
			}
		});
	}

	private static boolean isTranslated(Translations translations, String line)
	{
		String[] c = line.split("\t", -1);
		Scope scope = Scope.of(c.length > 2 ? c[2] : "", c.length > 3 ? c[3] : "", c.length > 4 ? c[4] : "");
		return TextLookup.translate(translations, c[0], scope) != null;
	}

	/** Client thread. {@code english} is the normalized lookup key. */
	void record(String english, Scope scope)
	{
		Session s = session;
		if (s == null || s.file == null || english.isEmpty())
		{
			return;
		}
		String line = String.join("\t", english, "", scope.getCategory(), scope.getSubCategory(), scope.getSource());
		if (!s.seen.add(keyOfLine(line)))
		{
			return;
		}
		executor.execute(() -> append(s, line));
	}

	private static void append(Session s, String line)
	{
		try
		{
			boolean fresh = !s.file.exists() || s.file.size() == 0;
			try (OutputStream out = s.file.openOutputStream(StandardOpenOption.CREATE, StandardOpenOption.APPEND))
			{
				out.write(((fresh ? HEADER : "") + line + "\n").getBytes(StandardCharsets.UTF_8));
			}
		}
		catch (IOException e)
		{
			log.warn("could not write missing text", e);
		}
	}

	/** english, category, sub_category and source; the translation column is ignored. */
	private static String keyOfLine(String line)
	{
		String[] c = line.split("\t", -1);
		StringBuilder key = new StringBuilder();
		for (int i : new int[]{0, 2, 3, 4})
		{
			key.append(i < c.length ? c[i] : "").append('\u0000');
		}
		return key.toString();
	}
}

package com.runetongue;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Shows the English of what the mouse is over in a tooltip, next to the Korean the game now
 * shows in its top-left text. RuneLingual's MouseTooltipOverlay did the reverse (English in the
 * game, Korean in the tooltip); either way both are on screen, which players used to check a
 * translation. The conditions for showing it are RuneLingual's.
 */
class OriginalTextTooltip extends Overlay
{
	private final Client client;
	private final TooltipManager tooltipManager;
	private final MenuTranslator menu;
	private final RuneTongueConfig config;

	@Inject
	OriginalTextTooltip(Client client, TooltipManager tooltipManager, MenuTranslator menu, RuneTongueConfig config)
	{
		this.client = client;
		this.tooltipManager = tooltipManager;
		this.menu = menu;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		// also above the full screen world map and the welcome screen
		drawAfterInterface(InterfaceID.TOPLEVEL_DISPLAY);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.originalTooltip() || client.isMenuOpen())
		{
			return null;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length == 0)
		{
			return null;
		}
		MenuEntry top = entries[entries.length - 1];
		String option = menu.originalOf(top.getOption());
		String target = menu.originalOf(top.getTarget());
		if ((option == null && target == null) || !worthShowing(top))
		{
			return null;
		}
		option = option != null ? option : top.getOption();
		target = target != null ? target : top.getTarget();
		tooltipManager.addFront(new Tooltip(target == null || target.isEmpty() ? option : option + " " + target));
		return null;
	}

	private boolean worthShowing(MenuEntry entry)
	{
		MenuAction type = entry.getType();
		if (type == MenuAction.RUNELITE_OVERLAY || type == MenuAction.CC_OP_LOW_PRIORITY
			|| type == MenuAction.WALK || type == MenuAction.CANCEL)
		{
			return false;
		}
		String option = menu.originalOf(entry.getOption());
		String target = menu.originalOf(entry.getTarget());
		if ("Continue".equals(option) || (target != null && target.contains("Slide")))
		{
			return false;
		}
		// The game is about to show, or is showing, its own tooltip.
		return client.getVarcIntValue(VarClientID.TOOLTIP_TIME) <= client.getGameCycle()
			&& client.getVarcIntValue(VarClientID.TOOLTIP_BUILT) != 1;
	}
}

