package com.runetongue;

import com.runetongue.text.ParseResult;
import java.awt.BorderLayout;
import java.awt.Font;
import java.awt.GridLayout;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.Filepath;

/** Side panel for the user translation folder. All methods run on the Swing EDT. */
class RuneTonguePanel extends PluginPanel
{
	static final int SKIPPED_LINES_PER_FILE = 50;
	private static final int DETAIL_LENGTH = 80;
	/** The RuneScape font RuneLite uses by default has no Hangul; this one falls back to OS fonts. */
	private static final Font FONT = FontManager.getDefaultFont().deriveFont(12f);

	private final JTextArea report = new JTextArea();
	private final JLabel missing = new JLabel(" ");
	private final JButton copyPathButton;
	private final JButton addFilesButton;
	private final JButton reloadButton;
	private final JButton saveMissingButton;
	private Language language;

	/**
	 * Plugin Hub plugins may not start other programs, so the panel cannot open the folder in the
	 * file manager: it copies the folder's path instead, adds files through a file chooser, and
	 * saves the untranslated-text file wherever the player picks.
	 */
	RuneTonguePanel(Language language, Runnable copyFolderPath, Consumer<List<Filepath>> addFiles, Runnable reload,
		Consumer<Filepath> saveMissing)
	{
		setLayout(new BorderLayout(0, 8));

		JPanel buttons = new JPanel(new GridLayout(0, 1, 0, 4));
		copyPathButton = button(copyFolderPath);
		addFilesButton = button(() -> chooseFiles(addFiles));
		reloadButton = button(reload);
		saveMissingButton = button(() -> chooseMissingTarget(saveMissing));
		buttons.add(copyPathButton);
		buttons.add(addFilesButton);
		buttons.add(reloadButton);
		buttons.add(saveMissingButton);
		missing.setFont(FONT);
		buttons.add(missing);
		add(buttons, BorderLayout.NORTH);

		report.setFont(FONT);
		report.setEditable(false);
		report.setLineWrap(true);
		report.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		report.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		add(report, BorderLayout.CENTER);
		setLanguage(language);
		report.setText(language.ui("불러오는 중…", "Loading…"));
	}

	/** The panel speaks Korean for Korean and English for the other languages. */
	private void setLanguage(Language language)
	{
		this.language = language;
		copyPathButton.setText(language.ui("폴더 경로 복사", "Copy folder path"));
		addFilesButton.setText(language.ui("파일 추가", "Add files"));
		reloadButton.setText(language.ui("다시 불러오기", "Reload"));
		saveMissingButton.setText(language.ui("빠진 문장 저장…", "Save untranslated text…"));
	}

	void show(LoadReport loaded)
	{
		setLanguage(loaded.getLanguage());
		report.setText(describe(loaded));
		report.setCaretPosition(0);
	}

	/** How many lines are waiting in missing/<lang>/missing.tsv. */
	void showMissing(int lines)
	{
		missing.setText(language.ui("빠진 문장 " + lines + "줄 모임 (번역하면 자동으로 지워짐)",
			lines + " untranslated lines collected (removed once translated)"));
	}

	void showMessage(String message)
	{
		report.setText(message);
	}

	private void chooseMissingTarget(Consumer<Filepath> saveMissing)
	{
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.addExtensionFilter("TSV (*.tsv)", "tsv")
			.setDefaultExtension("tsv")
			.setFileName("missing_" + language.getCode() + ".tsv")
			.setDialogTitle(language.ui("빠진 문장 저장", "Save untranslated text"))
			.showDialog(this);
		if (chosen != null && !chosen.isEmpty())
		{
			saveMissing.accept(chosen.get(0));
		}
	}

	private void chooseFiles(Consumer<List<Filepath>> addFiles)
	{
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsOpen()
			.setAcceptsFiles()
			.setMultiSelectionEnabled(true)
			.addExtensionFilter("TSV (*.tsv)", "tsv")
			.setDialogTitle(language.ui("번역 폴더에 넣을 tsv 파일", "tsv files to add to the translation folder"))
			.showDialog(this);
		if (chosen != null && !chosen.isEmpty())
		{
			addFiles.accept(chosen);
		}
	}

	private static JButton button(Runnable action)
	{
		JButton button = new JButton();
		button.setFont(FONT);
		button.addActionListener(e -> action.run());
		return button;
	}

	static String describe(LoadReport loaded)
	{
		Language lang = loaded.getLanguage();
		StringBuilder out = new StringBuilder();
		out.append(lang.ui("언어: ", "Language: ")).append(lang).append('\n');
		out.append(lang.ui("폴더: ", "Folder: ")).append(loaded.getFolder()).append("\n\n");
		out.append(loaded.summary()).append('\n');
		if (loaded.getError() == null && loaded.getFiles().isEmpty())
		{
			out.append('\n').append(lang.ui(
				"폴더에 tsv 파일이 없어요. '파일 추가'로 고르거나 '폴더 열기'로 직접 넣은 뒤 '다시 불러오기'를 누르세요.",
				"No tsv files in the folder yet. Pick some with 'Add files', or put them in with 'Open folder' and press 'Reload'."))
				.append('\n');
		}
		for (LoadReport.FileReport file : loaded.getFiles())
		{
			ParseResult result = file.getResult();
			out.append('\n').append(file.getFileName()).append(": ").append(String.format(
				lang.ui("%d줄 불러옴, %d줄 건너뜀, 미번역 %d줄", "%d loaded, %d skipped, %d untranslated"),
				file.loadedLines(), file.skippedLines(), result.getUntranslated())).append('\n');
			List<ParseResult.Skipped> skipped = result.getSkipped();
			int shown = Math.min(skipped.size(), SKIPPED_LINES_PER_FILE);
			for (ParseResult.Skipped s : skipped.subList(0, shown))
			{
				out.append("  ").append(loaded.skippedLine(s)).append('\n');
				if (!s.getDetail().isEmpty())
				{
					out.append("    ").append(shorten(s.getDetail())).append('\n');
				}
			}
			if (skipped.size() > shown)
			{
				out.append("  ").append(lang.ui("… 외 " + (skipped.size() - shown) + "줄", "… and " + (skipped.size() - shown) + " more")).append('\n');
			}
		}
		return out.toString();
	}

	private static String shorten(String detail)
	{
		String oneLine = detail.replace('\t', ' ');
		return oneLine.length() <= DETAIL_LENGTH ? oneLine : oneLine.substring(0, DETAIL_LENGTH) + "…";
	}
}

package com.runetongue;

import com.google.inject.Provides;
import com.runetongue.glyph.GlyphColor;
import com.runetongue.glyph.GlyphIcons;
import com.runetongue.text.Normalizer;
import com.runetongue.text.ParseResult;
import com.runetongue.text.Scope;
import com.runetongue.text.SkipReason;
import com.runetongue.text.SourceText;
import java.awt.Graphics2D;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.StandardCopyOption;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Filepath;

@Slf4j
@PluginDescriptor(
	name = "RuneTongue",
	description = "Play in Korean, or in your own language by dropping translation tsv files into a folder",
	tags = {"korean", "translation", "translate", "language", "spanish", "portuguese", "french", "german", "한국어"},
	internalName = "runetongue"
)
public class RuneTonguePlugin extends Plugin
{
	private static final String GLYPH_SAMPLE = "다람쥐 헌 쳇바퀴에 타고파, Lumbridge(럼브리지) 1,234gp 똠";
	private static final int SKIPPED_LINES_IN_CHAT = 5;
	private static final int ICON_SIZE = 16;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private RuneTongueConfig config;

	@Inject
	private GlyphIcons glyphIcons;

	@Inject
	private TranslationStore store;

	@Inject
	private DialogueTranslator dialogue;

	@Inject
	private MissingTexts missing;

	@Inject
	private MenuTranslator menu;

	@Inject
	private InterfaceTranslator interfaces;

	@Inject
	private ChatTranslator chatTranslator;

	@Inject
	private WidgetTexts widgetTexts;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private OriginalTextTooltip originalTooltip;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ScheduledExecutorService executor;

	private RuneTonguePanel panel;
	private NavigationButton navButton;
	/** A load that finished before login, shown in chat once the player logs in. Client thread only. */
	private LoadReport unannounced;

	@Override
	protected void startUp() throws Exception
	{
		panel = new RuneTonguePanel(config.language(), this::copyFolderPath, this::addFiles, () -> reload(true),
			this::saveMissing);
		navButton = NavigationButton.builder()
			.tooltip("RuneTongue")
			.icon(icon())
			.priority(10)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(originalTooltip);
		log.debug("RuneTongue started");
		missing.start(this::missingFolder);
		reload(false);
	}

	@Override
	protected void shutDown() throws Exception
	{
		store.stop();
		missing.stop();
		dialogue.reset();
		menu.reset();
		widgetTexts.reset();
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(originalTooltip);
		navButton = null;
		panel = null;
		unannounced = null;
		log.debug("RuneTongue stopped");
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (RuneTongueConfig.GROUP.equals(event.getGroup()) && RuneTongueConfig.LANGUAGE.equals(event.getKey()))
		{
			missing.start(this::missingFolder);
			reload(true);
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		dialogue.update();
		interfaces.update();
		menu.update();
	}

	@Subscribe(priority = -100)
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		chatTranslator.translateOverhead(event.getActor(), event.getOverheadText());
	}

	/** Late, so other plugins see the English message first. */
	@Subscribe(priority = -100)
	public void onChatMessage(ChatMessage event)
	{
		if (chatTranslator.translate(event.getMessageNode()))
		{
			client.refreshChat();
		}
	}

	/** Late, so the menu is translated after other plugins have changed it. */
	@Subscribe(priority = -100)
	public void onMenuOpened(MenuOpened event)
	{
		menu.update();
	}

	/** Early, so other plugins see the English option and target. */
	@Subscribe(priority = 100)
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		menu.restore(event.getMenuEntry());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN && unannounced != null)
		{
			announce(unannounced);
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		String[] args = event.getArguments();
		if ("hangul".equals(event.getCommand()))
		{
			for (GlyphColor color : GlyphColor.values())
			{
				chat(color.name().toLowerCase() + ": " + glyphIcons.toChatText(GLYPH_SAMPLE, color));
			}
		}
		else if ("rh".equals(event.getCommand()) && args.length >= 1 && "reload".equals(args[0]))
		{
			reload(true);
		}
		else if ("rh".equals(event.getCommand()) && args.length >= 2 && "find".equals(args[0]))
		{
			String english = String.join(" ", Arrays.copyOfRange(args, 1, args.length));
			SourceText source = Normalizer.normalizeSource(english);
			String found = store.get().find(source.getKey(), Scope.ANY);
			say(found == null ? english + config.language().ui(" -> 번역 없음", " -> no translation") : english + " -> " + Normalizer.restore(found, source));
		}
	}

	private Filepath folder() throws IOException
	{
		return getPluginDirectory().join("translations", config.language().getCode());
	}

	private Filepath missingFolder() throws IOException
	{
		return getPluginDirectory().join("missing", config.language().getCode());
	}

	private void reload(boolean announce)
	{
		RuneTonguePanel target = panel;
		if (target == null)
		{
			return;
		}
		store.reload(this::folder, config.language(), report ->
		{
			SwingUtilities.invokeLater(() -> target.show(report));
			missing.prune(store.get(), lines -> SwingUtilities.invokeLater(() -> target.showMissing(lines)));
			clientThread.invoke(() ->
			{
				menu.reset();
				widgetTexts.reset();
				dialogue.reset();
				if (announce || client.getGameState() == GameState.LOGGED_IN)
				{
					announce(report);
				}
				else
				{
					unannounced = report;
				}
			});
		});
	}

	/** Puts the translation folder's path on the clipboard, to paste into the file manager. */
	private void copyFolderPath()
	{
		executor.execute(() ->
		{
			try
			{
				Filepath dir = folder();
				dir.createDirectories();
				String path = dir.toString();
				SwingUtilities.invokeLater(() ->
				{
					Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(path), null);
					showMessage(config.language().ui("폴더 경로를 복사했어요. 파일 탐색기 주소창에 붙여 넣으세요:\n",
						"Copied the folder path. Paste it into your file manager's address bar:\n") + path);
				});
			}
			catch (Exception e)
			{
				log.warn("could not find the translation folder", e);
				showMessage(config.language().ui("폴더를 찾지 못했어요: ", "Could not find the folder: ") + e.getMessage());
			}
		});
	}

	/** Copies missing/<lang>/missing.tsv to where the player chose to save it. */
	private void saveMissing(Filepath target)
	{
		executor.execute(() ->
		{
			try
			{
				Filepath source = missingFolder().join(MissingTexts.FILE_NAME);
				if (!source.exists())
				{
					showMessage(config.language().ui("아직 모인 빠진 문장이 없어요.", "No untranslated text has been collected yet."));
					return;
				}
				source.copyTo(target, StandardCopyOption.REPLACE_EXISTING);
				showMessage(config.language().ui("빠진 문장을 저장했어요: ", "Saved the untranslated text to: ") + target);
			}
			catch (Exception e)
			{
				log.warn("could not save the missing text file", e);
				showMessage(config.language().ui("파일을 저장하지 못했어요: ", "Could not save the file: ") + e.getMessage());
			}
		});
	}

	private void addFiles(List<Filepath> chosen)
	{
		executor.execute(() ->
		{
			try
			{
				Filepath dir = folder();
				dir.createDirectories();
				for (Filepath file : chosen)
				{
					// A file already in the folder copies onto itself, which Files.copy skips.
					file.copyTo(dir.join(file.getFileName()), StandardCopyOption.REPLACE_EXISTING);
				}
				reload(true);
			}
			catch (Exception e)
			{
				log.warn("could not copy translation files", e);
				showMessage(config.language().ui("파일을 복사하지 못했어요: ", "Could not copy the files: ") + e.getMessage());
			}
		});
	}

	private void showMessage(String message)
	{
		RuneTonguePanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.showMessage(message));
		}
	}

	private BufferedImage icon()
	{
		BufferedImage glyph = glyphIcons.image('한', GlyphColor.ORANGE);
		BufferedImage icon = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.drawImage(glyph, (ICON_SIZE - glyph.getWidth()) / 2, (ICON_SIZE - glyph.getHeight()) / 2, null);
		g.dispose();
		return icon;
	}

	private void announce(LoadReport report)
	{
		unannounced = null;
		say(report.summary());
		if (report.getError() != null)
		{
			return;
		}
		int shown = 0;
		for (LoadReport.FileReport file : report.getFiles())
		{
			for (ParseResult.Skipped s : file.getResult().getSkipped())
			{
				if (s.getReason() == SkipReason.OVERRIDDEN)
				{
					continue;
				}
				if (shown++ == SKIPPED_LINES_IN_CHAT)
				{
					say("…");
					return;
				}
				say(file.getFileName() + " " + report.skippedLine(s));
			}
		}
	}

	private void say(String text)
	{
		chat("RuneTongue: " + glyphIcons.toChatText(text, GlyphColor.BLACK));
	}

	private void chat(String markup)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", markup, null);
	}

	@Provides
	RuneTongueConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RuneTongueConfig.class);
	}
}

package com.runetongue;

import com.runetongue.text.Entry;
import com.runetongue.text.ParseResult;
import com.runetongue.text.TranslationTable;
import com.runetongue.text.Translations;
import com.runetongue.text.TsvParser;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.Callable;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import java.util.zip.GZIPInputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Holds the active translations. Loading runs on the executor and swaps in a finished,
 * immutable {@link Translations}, so the client thread only ever reads.
 */
@Slf4j
@Singleton
public class TranslationStore
{
	private final ScheduledExecutorService executor;
	private volatile Translations translations = Translations.EMPTY;
	private final Object bundledLock = new Object();
	private Future<?> pending;
	private int generation;
	private Language bundledLanguage;
	private TranslationTable bundled = TranslationTable.EMPTY;

	@Inject
	TranslationStore(ScheduledExecutorService executor)
	{
		this.executor = executor;
	}

	public Translations get()
	{
		return translations;
	}

	/** False until the first load finishes (and after stop), when every lookup misses. */
	public boolean isLoaded()
	{
		return translations != Translations.EMPTY;
	}

	public synchronized void reload(Callable<Filepath> folder, Language language, Consumer<LoadReport> onDone)
	{
		cancelPending();
		int current = ++generation;
		pending = executor.submit(() ->
		{
			LoadReport report = load(folder, language, current);
			if (report != null)
			{
				onDone.accept(report);
			}
		});
	}

	public synchronized void stop()
	{
		cancelPending();
		generation++;
		translations = Translations.EMPTY;
	}

	private void cancelPending()
	{
		if (pending != null)
		{
			pending.cancel(true);
			pending = null;
		}
	}

	private LoadReport load(Callable<Filepath> folder, Language language, int current)
	{
		long start = System.nanoTime();
		TranslationTable bundledTable = bundledFor(language);
		List<LoadReport.FileReport> files = new ArrayList<>();
		String folderName = "";
		String error = null;
		try
		{
			Filepath dir = folder.call();
			dir.createDirectories();
			folderName = dir.toString();
			for (Filepath file : tsvFiles(dir))
			{
				if (Thread.currentThread().isInterrupted())
				{
					return null;
				}
				try (InputStream in = file.openInputStream())
				{
					files.add(new LoadReport.FileReport(file.getFileName(), TsvParser.parse(in.readAllBytes())));
				}
			}
		}
		catch (Exception e)
		{
			log.warn("could not read translation folder", e);
			error = String.valueOf(e.getMessage());
		}

		List<Entry> entries = new ArrayList<>();
		for (LoadReport.FileReport f : files)
		{
			entries.addAll(f.getResult().getEntries());
		}
		Translations loaded = new Translations(new TranslationTable(entries), bundledTable);
		synchronized (this)
		{
			if (current != generation)
			{
				return null;
			}
			translations = loaded;
		}
		log.debug("loaded {} user files and {} bundled entries for {} in {} ms",
			files.size(), bundledTable.size(), language, (System.nanoTime() - start) / 1_000_000);
		return new LoadReport(language, folderName, files, bundledTable.size(), error);
	}

	private static List<Filepath> tsvFiles(Filepath dir) throws IOException
	{
		try (Stream<Filepath> walk = dir.walk(1))
		{
			return walk
				.filter(Filepath::isFile)
				.filter(f -> f.getFileName().toLowerCase(Locale.ROOT).endsWith(".tsv"))
				.sorted(Comparator.comparing(Filepath::getFileName))
				.collect(Collectors.toList());
		}
	}

	private TranslationTable bundledFor(Language language)
	{
		synchronized (bundledLock)
		{
			if (language != bundledLanguage)
			{
				bundled = readBundled(language);
				bundledLanguage = language;
			}
			return bundled;
		}
	}

	private static TranslationTable readBundled(Language language)
	{
		String resource = language.getBundledResource();
		if (resource == null)
		{
			return TranslationTable.EMPTY;
		}
		try (InputStream raw = TranslationStore.class.getResourceAsStream(resource))
		{
			if (raw == null)
			{
				log.debug("no bundled translations at {}", resource);
				return TranslationTable.EMPTY;
			}
			try (InputStream in = new GZIPInputStream(raw))
			{
				ParseResult result = TsvParser.parse(in.readAllBytes());
				return new TranslationTable(result.getEntries());
			}
		}
		catch (IOException e)
		{
			log.warn("could not read bundled translations", e);
			return TranslationTable.EMPTY;
		}
	}
}

