package com.runetongue.text;

import java.util.Map;

/**
 * One lookup of game text: the plain key first, then the partial templates. Pure, so the
 * plugin and tests share it.
 */
public final class TextLookup
{
	private TextLookup()
	{
	}

	/** The translation of {@code english} with its numbers and colors put back, or null. */
	public static String translate(Translations t, String english, Scope scope)
	{
		return translate(t, english, scope, true);
	}

	private static String translate(Translations t, String english, Scope scope, boolean withTemplates)
	{
		SourceText source = Normalizer.normalizeSource(english);
		String found = t.find(source.getKey(), scope);
		if (found != null)
		{
			return Normalizer.restore(found, source);
		}
		return withTemplates ? fromTemplate(t, english, scope) : null;
	}

	/**
	 * Text with a part translated separately or kept as is, such as "Name: Zezima" or "Monster:
	 * Giant Mole" (see {@link PartialTemplate}). Unknown text of this kind is never recorded: it
	 * usually holds a player's name.
	 */
	private static String fromTemplate(Translations t, String english, Scope scope)
	{
		for (PartialTemplate template : t.templates())
		{
			Map<String, String> filled = template.match(english);
			if (filled == null)
			{
				continue;
			}
			SourceText source = Normalizer.normalizeSource(template.unfill(english, filled));
			if (!source.getKey().equals(template.getKey()))
			{
				continue;
			}
			String found = t.findTemplate(template.getKey(), scope);
			if (found == null)
			{
				continue;
			}
			String text = Normalizer.restore(found, source);
			for (Map.Entry<String, String> slot : filled.entrySet())
			{
				String part = slotText(t, slot.getKey(), slot.getValue());
				if (part == null)
				{
					return null;
				}
				text = text.replace("<!" + slot.getKey() + ">", part);
			}
			return text;
		}
		return null;
	}

	/** A slot's translation by its kind, as RuneLingual's PartialTranslationManager did; null if it has none. */
	private static String slotText(Translations t, String slot, String content)
	{
		switch (PartialTemplate.typeOf(slot))
		{
			case "PLAYER_NAME":
				return content;
			case "NPC_NAME":
				return translate(t, content, Scope.of("name", "npc", ""), false);
			case "ITEM_NAME":
				return translate(t, content, Scope.of("name", "item", ""), false);
			case "OBJECT_NAME":
				return translate(t, content, Scope.of("name", "object", ""), false);
			default:
				return translate(t, content, Scope.ANY, false);
		}
	}

}

package com.runetongue.text;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Immutable lookup for one layer (the bundled data, or all user files together). Every line for
 * one English key is kept with its scope, so a lookup can fall back from an exact scope match to
 * a looser one. {@link Translations} decides the order across layers.
 */
public final class TranslationTable
{
	public static final TranslationTable EMPTY = new TranslationTable(Collections.emptyList());

	private static final class Candidate
	{
		final Scope scope;
		final String translation;

		Candidate(Scope scope, String translation)
		{
			this.scope = scope;
			this.translation = translation;
		}
	}

	private final Map<String, Candidate[]> byEnglish = new HashMap<>();
	private final List<PartialTemplate> templates = new ArrayList<>();
	private final int size;

	/** Later entries win, so pass files in name order and lines in file order. */
	public TranslationTable(Iterable<Entry> entries)
	{
		Map<Scope, Scope> scopes = new HashMap<>();
		int count = 0;
		for (Entry e : entries)
		{
			Candidate c = new Candidate(scopes.computeIfAbsent(e.getScope(), s -> s), e.getTranslation());
			Candidate[] old = byEnglish.get(e.getEnglish());
			if (old == null)
			{
				byEnglish.put(e.getEnglish(), new Candidate[]{c});
				count++;
				continue;
			}
			int same = indexOf(old, c.scope);
			if (same >= 0)
			{
				old[same] = c;
				continue;
			}
			Candidate[] grown = Arrays.copyOf(old, old.length + 1);
			grown[old.length] = c;
			byEnglish.put(e.getEnglish(), grown);
			count++;
		}
		size = count;
		for (String english : byEnglish.keySet())
		{
			if (PartialTemplate.isTemplate(english))
			{
				templates.add(PartialTemplate.of(english));
			}
		}
	}

	/** Lines with {@code <!TYPEn>} slots (see {@link PartialTemplate}). */
	public List<PartialTemplate> templates()
	{
		return Collections.unmodifiableList(templates);
	}

	/**
	 * A line whose scope is the asked scope or a broader one (a line with no category applies
	 * everywhere), most specific first.
	 */
	public String exact(String english, Scope scope)
	{
		Candidate[] candidates = byEnglish.get(english);
		if (candidates == null)
		{
			return null;
		}
		for (Scope level : scope.widening())
		{
			for (int i = candidates.length - 1; i >= 0; i--)
			{
				if (candidates[i].scope.equals(level))
				{
					return candidates[i].translation;
				}
			}
		}
		return null;
	}

	/**
	 * A line that agrees with the asked scope on as many leading fields as possible, ignoring the
	 * rest: same category and sub_category but another source, then same category, then anything.
	 */
	public String relaxed(String english, Scope scope)
	{
		return relaxed(english, scope, false);
	}

	/** {@link #relaxed}, optionally only among lines with the asked category and sub_category. */
	public String relaxed(String english, Scope scope, boolean sameSubCategory)
	{
		Candidate[] candidates = byEnglish.get(english);
		if (candidates == null)
		{
			return null;
		}
		for (Scope level : scope.widening())
		{
			if (sameSubCategory && level.getSubCategory().isEmpty())
			{
				break;
			}
			for (int i = candidates.length - 1; i >= 0; i--)
			{
				if (candidates[i].scope.isWithin(level))
				{
					return candidates[i].translation;
				}
			}
		}
		return null;
	}

	/** Distinct (English, scope) pairs. */
	public int size()
	{
		return size;
	}

	private static int indexOf(Candidate[] candidates, Scope scope)
	{
		for (int i = 0; i < candidates.length; i++)
		{
			if (candidates[i].scope.equals(scope))
			{
				return i;
			}
		}
		return -1;
	}
}

package com.runetongue.text;

import java.util.ArrayList;
import java.util.List;

/**
 * User files over the bundled data. An exact scope match in either layer beats any looser match;
 * within each kind, the user layer is asked first. So a user line with no category overrides the
 * bundled data everywhere, but a user line for one category does not override another category's
 * exact bundled line.
 */
public final class Translations
{
	public static final Translations EMPTY = new Translations(TranslationTable.EMPTY, TranslationTable.EMPTY);

	private final TranslationTable user;
	private final TranslationTable bundled;

	public Translations(TranslationTable user, TranslationTable bundled)
	{
		this.user = user;
		this.bundled = bundled;
	}

	/** Templates from both layers; a template is found with {@link #findTemplate}. */
	public List<PartialTemplate> templates()
	{
		List<PartialTemplate> all = new ArrayList<>(user.templates());
		all.addAll(bundled.templates());
		return all;
	}

	/**
	 * A template's translation, only from lines of the asked category and sub_category: a template
	 * such as {@code <!ANY_TRANSLATED0> (<Num0>)} would otherwise fit text anywhere.
	 */
	public String findTemplate(String english, Scope scope)
	{
		String t = user.exact(english, scope);
		if (t == null)
		{
			t = bundled.exact(english, scope);
		}
		if (t == null)
		{
			t = user.relaxed(english, scope, true);
		}
		if (t == null)
		{
			t = bundled.relaxed(english, scope, true);
		}
		return t;
	}

	public String find(String english, Scope scope)
	{
		String t = user.exact(english, scope);
		if (t == null)
		{
			t = bundled.exact(english, scope);
		}
		if (t == null)
		{
			t = user.relaxed(english, scope);
		}
		if (t == null)
		{
			t = bundled.relaxed(english, scope);
		}
		return t;
	}
}

package com.runetongue.text;

import java.nio.ByteBuffer;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.Charset;
import java.nio.charset.CharsetDecoder;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Reads translation tsv files: the bundled data, hand-made files and filled-in exports alike.
 * Bad lines are skipped and reported; the rest of the file still loads.
 */
public final class TsvParser
{
	private static final List<String> DEFAULT_COLUMNS = Arrays.asList("english", "translation", "category", "sub_category", "source");
	private static final char REPLACEMENT = '�';

	private TsvParser()
	{
	}

	public static ParseResult parse(byte[] bytes)
	{
		String[] lines = decode(bytes).split("\r?\n", -1);
		List<String> columns = DEFAULT_COLUMNS;
		int first = 0;
		List<String> header = new ArrayList<>();
		for (String name : lines[0].split("\t", -1))
		{
			header.add(name.trim().toLowerCase(Locale.ROOT));
		}
		if (header.contains("english") && header.contains("translation"))
		{
			columns = header;
			first = 1;
		}
		Columns col = new Columns(columns);

		Map<String, Entry> entries = new LinkedHashMap<>();
		List<ParseResult.Skipped> skipped = new ArrayList<>();
		Set<Integer> overriddenLines = new HashSet<>();
		int untranslated = 0;
		for (int i = first; i < lines.length; i++)
		{
			int lineNo = i + 1;
			String line = lines[i];
			if (line.trim().isEmpty())
			{
				continue;
			}
			if (line.indexOf(REPLACEMENT) >= 0)
			{
				skipped.add(new ParseResult.Skipped(lineNo, SkipReason.BAD_ENCODING, ""));
				continue;
			}
			String[] cells = line.split("\t", -1);
			if (cells.length < 2)
			{
				skipped.add(new ParseResult.Skipped(lineNo, SkipReason.TOO_FEW_COLUMNS, line));
				continue;
			}
			String english = col.get(cells, "english");
			String translation = col.get(cells, "translation");
			if (english.isEmpty())
			{
				skipped.add(new ParseResult.Skipped(lineNo, SkipReason.EMPTY_ENGLISH, line));
				continue;
			}
			if (translation.isEmpty())
			{
				untranslated++;
				continue;
			}
			Scope scope = Scope.of(col.get(cells, "category"), col.get(cells, "sub_category"), col.get(cells, "source"));

			List<Entry> lineEntries = new ArrayList<>();
			ParseResult.Skipped problem = expand(english, translation, scope, lineNo, lineEntries);
			if (problem != null)
			{
				skipped.add(problem);
				continue;
			}
			for (Entry e : lineEntries)
			{
				Entry previous = entries.put(e.getEnglish() + '\t' + scope, e);
				if (previous != null && previous.getLine() != lineNo
					&& !previous.getTranslation().equals(e.getTranslation())
					&& overriddenLines.add(previous.getLine()))
				{
					skipped.add(new ParseResult.Skipped(previous.getLine(), SkipReason.OVERRIDDEN, "-> " + lineNo));
				}
			}
		}
		skipped.sort((a, b) -> Integer.compare(a.getLine(), b.getLine()));
		return new ParseResult(new ArrayList<>(entries.values()), skipped, untranslated);
	}

	private static ParseResult.Skipped expand(String english, String translation, Scope scope, int lineNo, List<Entry> out)
	{
		int count = Choices.count(english);
		int translationCount = Choices.count(translation);
		if (count < 0 || translationCount < 0 || (translationCount != 1 && translationCount != count))
		{
			return new ParseResult.Skipped(lineNo, SkipReason.CHOICE_MISMATCH, english + " / " + translation);
		}
		List<String> englishVariants = Choices.expand(english, count);
		List<String> translationVariants = Choices.expand(translation, count);
		for (int k = 0; k < count; k++)
		{
			SourceText source = Normalizer.normalizeSource(englishVariants.get(k));
			String normalized = Normalizer.normalizeTranslation(translationVariants.get(k), source);
			Set<String> expected = Normalizer.placeholders(source.getKey());
			Set<String> actual = Normalizer.placeholders(normalized);
			if (!expected.equals(actual))
			{
				return new ParseResult.Skipped(lineNo, SkipReason.PLACEHOLDER_MISMATCH, "english " + expected + ", translation " + actual);
			}
			out.add(new Entry(source.getKey(), normalized, scope, lineNo));
		}
		return null;
	}

	private static String decode(byte[] bytes)
	{
		Charset charset = StandardCharsets.UTF_8;
		int offset = 0;
		if (bytes.length >= 3 && (bytes[0] & 0xFF) == 0xEF && (bytes[1] & 0xFF) == 0xBB && (bytes[2] & 0xFF) == 0xBF)
		{
			offset = 3;
		}
		else if (bytes.length >= 2 && (bytes[0] & 0xFF) == 0xFF && (bytes[1] & 0xFF) == 0xFE)
		{
			charset = StandardCharsets.UTF_16LE;
			offset = 2;
		}
		else if (bytes.length >= 2 && (bytes[0] & 0xFF) == 0xFE && (bytes[1] & 0xFF) == 0xFF)
		{
			charset = StandardCharsets.UTF_16BE;
			offset = 2;
		}
		CharsetDecoder decoder = charset.newDecoder()
			.onMalformedInput(CodingErrorAction.REPLACE)
			.onUnmappableCharacter(CodingErrorAction.REPLACE)
			.replaceWith(String.valueOf(REPLACEMENT));
		try
		{
			return decoder.decode(ByteBuffer.wrap(bytes, offset, bytes.length - offset)).toString();
		}
		catch (CharacterCodingException e)
		{
			throw new IllegalStateException("decoder set to REPLACE cannot fail", e);
		}
	}

	private static String cell(String[] cells, int index)
	{
		if (index < 0 || index >= cells.length)
		{
			return "";
		}
		String value = cells[index].trim();
		if (value.length() >= 2 && value.startsWith("\"") && value.endsWith("\"") && value.contains("\"\""))
		{
			value = value.substring(1, value.length() - 1).replace("\"\"", "\"");
		}
		return value;
	}

	private static final class Columns
	{
		private final List<String> names;

		Columns(List<String> names)
		{
			this.names = names;
		}

		String get(String[] cells, String name)
		{
			return cell(cells, names.indexOf(name));
		}
	}
}

package com.runetongue;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import com.runetongue.text.Entry;
import com.runetongue.text.TsvParser;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import java.util.zip.GZIPInputStream;
import org.junit.Test;

/**
 * The bundled translations are committed (the Plugin Hub builds with its own build.gradle, which
 * would skip the bundler), so this fails when data/ko was edited without running
 * {@code ./gradlew bundleTranslations}.
 */
public class BundledTranslationsTest
{
	@Test
	public void bundleMatchesTheDataFolder() throws IOException
	{
		Map<String, String> fromData = new LinkedHashMap<>();
		List<Path> files;
		try (Stream<Path> paths = Files.list(Paths.get("data/ko")))
		{
			files = paths.filter(p -> p.toString().endsWith(".tsv")).sorted().collect(Collectors.toList());
		}
		for (Path file : files)
		{
			addAll(fromData, TsvParser.parse(Files.readAllBytes(file)).getEntries());
		}

		Map<String, String> fromBundle = new LinkedHashMap<>();
		try (InputStream raw = BundledTranslationsTest.class.getResourceAsStream(Language.KOREAN.getBundledResource()))
		{
			assertNotNull("missing " + Language.KOREAN.getBundledResource(), raw);
			try (InputStream in = new GZIPInputStream(raw))
			{
				addAll(fromBundle, TsvParser.parse(in.readAllBytes()).getEntries());
			}
		}

		assertEquals("run ./gradlew bundleTranslations after editing data/ko", "", firstDifference(fromData, fromBundle));
	}

	/** A short description of the first line that differs, so a failure does not print 125,000 lines. */
	private static String firstDifference(Map<String, String> data, Map<String, String> bundle)
	{
		for (Map.Entry<String, String> e : data.entrySet())
		{
			String bundled = bundle.get(e.getKey());
			if (!e.getValue().equals(bundled))
			{
				return e.getKey().replace('\u0000', ' ') + ": data has \"" + e.getValue() + "\", bundle has \"" + bundled + "\"";
			}
		}
		return data.size() == bundle.size() ? "" : "bundle has " + (bundle.size() - data.size()) + " lines that data does not";
	}

	/** Later lines win, as they do when the plugin builds its lookup table. */
	private static void addAll(Map<String, String> into, List<Entry> entries)
	{
		for (Entry e : entries)
		{
			into.put(e.getScope() + "\u0000" + e.getEnglish(), e.getTranslation());
		}
	}
}

package com.runetongue;

import static org.junit.Assert.assertEquals;
import com.runetongue.text.Scope;
import com.runetongue.text.TranslationTable;
import com.runetongue.text.Translations;
import com.runetongue.text.TsvParser;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.util.Filepath;
import org.junit.Test;

public class MissingTextsTest
{
	private static final Scope HANS = Scope.of("dialogue", "Hans", "Hans");

	/** Runs one session on its own executor and waits for its writes. */
	private static void session(Path dir, String... englishLines) throws Exception
	{
		ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
		MissingTexts missing = new MissingTexts(executor);
		missing.start(() -> Filepath.Unchecked.getRooted(dir));
		executor.submit(() -> null).get();
		for (String english : englishLines)
		{
			missing.record(english, HANS);
		}
		executor.shutdown();
		executor.awaitTermination(5, TimeUnit.SECONDS);
	}

	@Test
	public void writesEachTextOnceAcrossSessions() throws Exception
	{
		Path dir = Files.createTempDirectory("missing");
		session(dir, "Hello there.", "You have <Num0> coins.", "Hello there.");
		session(dir, "Hello there.", "Goodbye.");

		List<String> lines = Files.readAllLines(dir.resolve(MissingTexts.FILE_NAME), StandardCharsets.UTF_8);
		assertEquals(List.of(
			"english\ttranslation\tcategory\tsub_category\tsource",
			"Hello there.\t\tdialogue\tHans\tHans",
			"You have <Num0> coins.\t\tdialogue\tHans\tHans",
			"Goodbye.\t\tdialogue\tHans\tHans"), lines);
	}

	@Test
	public void theFileLoadsAsAUserTranslationFile() throws Exception
	{
		Path dir = Files.createTempDirectory("missing");
		session(dir, "Hello there.", "You have <Num0> coins.");

		byte[] bytes = Files.readAllBytes(dir.resolve(MissingTexts.FILE_NAME));
		assertEquals(2, TsvParser.parse(bytes).getUntranslated());
		assertEquals(List.of(), TsvParser.parse(bytes).getSkipped());
	}

	@Test
	public void dropsLinesThatAreNowTranslated() throws Exception
	{
		Path dir = Files.createTempDirectory("missing");
		session(dir, "Hello there.", "You have <Num0> coins.");
		Translations translated = new Translations(new TranslationTable(TsvParser.parse(
			"You have 5 coins.\t코인이 5개 있어요.\tdialogue\n".getBytes(StandardCharsets.UTF_8)).getEntries()), TranslationTable.EMPTY);

		ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
		MissingTexts missing = new MissingTexts(executor);
		missing.start(() -> Filepath.Unchecked.getRooted(dir));
		AtomicInteger left = new AtomicInteger(-1);
		missing.prune(translated, left::set);
		executor.shutdown();
		executor.awaitTermination(5, TimeUnit.SECONDS);

		assertEquals(1, left.get());
		assertEquals(List.of("english\ttranslation\tcategory\tsub_category\tsource", "Hello there.\t\tdialogue\tHans\tHans"),
			Files.readAllLines(dir.resolve(MissingTexts.FILE_NAME), StandardCharsets.UTF_8));
	}
}

