import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;
import org.junit.Test;

/**
 * The reference PNGs come from RuneLingual's update_char_images.py, which the Korean glyphs
 * were tuned against in game. Its shadows are pure black, which never showed in game, so the
 * comparison maps them to the shadow color we draw.
 */
public class GlyphRendererTest
{
	private static final String CHARS = "한뷁g,yW";

	private final GlyphRenderer renderer = GlyphRenderer.bundled();

	@Test
	public void matchesRuneLingualImages() throws IOException
	{
		for (GlyphColor color : GlyphColor.values())
		{
			for (int cp : CHARS.codePoints().toArray())
			{
				String name = color.name().toLowerCase() + "--" + cp + ".png";
				assertSamePixels(name, reference(name), renderer.render(cp, color));
			}
		}
	}

	@Test
	public void bundledFontCoversOnlyTheSubset()
	{
		assertTrue(renderer.canDisplay('한'));
		assertFalse(renderer.canDisplay('똠'));
	}

	private static BufferedImage reference(String name) throws IOException
	{
		try (InputStream in = GlyphRendererTest.class.getResourceAsStream(name))
		{
			assertNotNull(name, in);
			return ImageIO.read(in);
		}
	}

	private static void assertSamePixels(String name, BufferedImage expected, BufferedImage actual)
	{
		assertEquals(name + " width", expected.getWidth(), actual.getWidth());
		assertEquals(name + " height", expected.getHeight(), actual.getHeight());
		for (int y = 0; y < expected.getHeight(); y++)
		{
			for (int x = 0; x < expected.getWidth(); x++)
			{
				assertEquals(name + " at " + x + "," + y, visible(expected.getRGB(x, y)), visible(actual.getRGB(x, y)));
			}
		}
	}

	private static int visible(int argb)
	{
		if ((argb >>> 24) == 0)
		{
			return 0;
		}
		return argb == 0xFF000000 ? GlyphColor.YELLOW.getShadow().getRGB() : argb;
	}

	@Test
	public void noOpaquePureBlackPixels()
	{
		for (GlyphColor color : GlyphColor.values())
		{
			BufferedImage image = renderer.render('한', color);
			for (int y = 0; y < image.getHeight(); y++)
			{
				for (int x = 0; x < image.getWidth(); x++)
				{
					assertTrue(color + " at " + x + "," + y + " would turn transparent in game", image.getRGB(x, y) != 0xFF000000);
				}
			}
		}
	}
}

package com.runetongue.text;

import static org.junit.Assert.assertEquals;
import java.util.List;
import java.util.function.IntUnaryOperator;
import org.junit.Test;

public class LineBreakerTest
{
	/** Hangul 12px, everything else 6px, like a game font next to the glyph images. */
	private static final IntUnaryOperator WIDTH = cp -> cp >= 0xAC00 && cp <= 0xD7A3 ? 12 : 6;

	@Test
	public void breaksAtSpacesUsingRealWidths()
	{
		// "가나다" = 36, " " = 6, "ab" = 12: 36 + 6 + 12 = 54 fits in 54, the next word does not.
		assertEquals(List.of("가나다 ab", "라마"), LineBreaker.wrap("가나다 ab 라마", 54, WIDTH));
	}

	@Test
	public void mixedTextIsNotBrokenEarly()
	{
		// 12px per character would count 228px; the line is really 126 + 6 + 24 = 156px.
		assertEquals(List.of("Lumbridge(럼브리지)에 가요"), LineBreaker.wrap("Lumbridge(럼브리지)에 가요", 160, WIDTH));
	}

	@Test
	public void keepsForcedBreaks()
	{
		assertEquals(List.of("가나", "다라"), LineBreaker.wrap("가나<br>다라", 500, WIDTH));
	}

	@Test
	public void breaksAWordWiderThanTheLine()
	{
		assertEquals(List.of("가나다", "라마"), LineBreaker.wrap("가나다라마", 36, WIDTH));
		assertEquals(List.of("ab", "가나다", "라마"), LineBreaker.wrap("ab 가나다라마", 36, WIDTH));
	}

	@Test
	public void tagsTakeNoWidthAndStayWhole()
	{
		assertEquals(24, LineBreaker.width("<col=ff0000>가나</col>", WIDTH));
		assertEquals(List.of("<col=ff0000>가나", "다</col>"), LineBreaker.wrap("<col=ff0000>가나다</col>", 24, WIDTH));
	}
}

package com.runetongue.text;

import static org.junit.Assert.assertEquals;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class NormalizerTest
{
	@Test
	public void replacesNumbersAndColorsButLeavesOtherTags()
	{
		SourceText s = Normalizer.normalizeSource(" <col=ff0000>Nex</col> (level-1,001)<br><img=12> ");
		assertEquals("<colNum0>Nex</col> (level-<Num0>)<br><img=12>", s.getKey());
		assertEquals(List.of("1,001"), s.getNumbers());
		assertEquals(List.of("<col=ff0000>"), s.getColors());
	}

	@Test
	public void keepsExistingPlaceholdersAndNumbersAfterThem()
	{
		SourceText s = Normalizer.normalizeSource("<Num0> of 10");
		assertEquals("<Num0> of <Num1>", s.getKey());
	}

	@Test
	public void restoresLiveValuesIntoTranslation()
	{
		SourceText live = Normalizer.normalizeSource("Wave <col=ffff00>3</col> of 7");
		assertEquals("Wave <colNum0><Num0></col> of <Num1>", live.getKey());
		assertEquals("7 중 <col=ffff00>3</col>번째", Normalizer.restore("<Num1> 중 <colNum0><Num0></col>번째", live));
	}

	@Test
	public void numbersNotInSourceStayLiteral()
	{
		SourceText s = Normalizer.normalizeSource("A dozen eggs");
		assertEquals("달걀 12개", Normalizer.normalizeTranslation("달걀 12개", s));
	}

	@Test
	public void findsPlaceholders()
	{
		assertEquals(Set.of("<Num0>", "<colNum0>", "[player name]"),
			Normalizer.placeholders("[player name] has <colNum0><Num0></col> and <Num0>"));
	}
}

package com.runetongue.text;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.Map;
import org.junit.Test;

public class PartialTemplateTest
{
	@Test
	public void fillsSlotsAroundFixedText()
	{
		PartialTemplate t = PartialTemplate.of("Name: <!PLAYER_NAME0>");
		assertEquals(Map.of("PLAYER_NAME0", "Zezima 2"), t.match("Name: Zezima 2"));
		assertNull(t.match("Username: Zezima"));
	}

	@Test
	public void colorTagsAndNumbersMatchAnyValue()
	{
		PartialTemplate monster = PartialTemplate.of("Monster: <colNum0><!NPC_NAME0></col>");
		assertEquals(Map.of("NPC_NAME0", "Giant Mole"), monster.match("Monster: <col=ffffff>Giant Mole</col>"));

		PartialTemplate boss = PartialTemplate.of("<!ANY_TRANSLATED0> (<Num0>)");
		assertEquals(Map.of("ANY_TRANSLATED0", "Wintertodt"), boss.match("Wintertodt (1,234)"));
	}

	@Test
	public void unfillGivesTheTemplateKeyAfterNormalizing()
	{
		// A player name with digits must not turn into a <Num> placeholder of the template.
		PartialTemplate t = PartialTemplate.of("Combat Profile - <!PLAYER_NAME0>");
		String shown = "Combat Profile - AngryCat9605";
		String unfilled = t.unfill(shown, t.match(shown));
		assertEquals("Combat Profile - <!PLAYER_NAME0>", unfilled);
		assertEquals(t.getKey(), Normalizer.normalizeSource(unfilled).getKey());

		PartialTemplate boss = PartialTemplate.of("<!ANY_TRANSLATED0> (<Num0>)");
		String bossShown = "Zulrah (25)";
		assertEquals(boss.getKey(), Normalizer.normalizeSource(boss.unfill(bossShown, boss.match(bossShown))).getKey());
	}

	@Test
	public void slotTypes()
	{
		assertEquals("NPC_NAME", PartialTemplate.typeOf("NPC_NAME0"));
		assertEquals("ANY_TRANSLATED", PartialTemplate.typeOf("ANY_TRANSLATED12"));
	}
}

package com.runetongue.text;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

public class TextLookupTest
{
	/** Template lines as they are in data/ko, plus the names they refer to. */
	private static final Translations DATA = new Translations(TranslationTable.EMPTY, new TranslationTable(TsvParser.parse((
		"english\ttranslation\tcategory\tsub_category\tsource\n"
			+ "Name: <!PLAYER_NAME0>\t이름: <!PLAYER_NAME0>\tinterface\tmainTabs\taccountManagementTab\n"
			+ "Monster: <colNum0><!NPC_NAME0></col>\t몬스터: <colNum0><!NPC_NAME0></col>\tinterface\tcombAchvmt\t\n"
			+ "<!ANY_TRANSLATED0> (<Num0>)\t<!ANY_TRANSLATED0> (<Num0>)\tinterface\tcombAchvmt\t\n"
			+ "Giant Mole\tGiant Mole(자이언트 몰)\tname\tnpc\tGiant Mole\n"
			+ "Wintertodt\tWintertodt(윈터토트)\tmanual\tlocation\t\n"
			+ "Filters\t필터\tinterface\tmainTabs\tprayerTab\n").getBytes(StandardCharsets.UTF_8)).getEntries()));

	private static final Scope ACCOUNT = Scope.of("interface", "mainTabs", "accountManagementTab");
	private static final Scope COMBAT_ACHIEVEMENTS = Scope.of("interface", "combAchvmt", "");

	@Test
	public void plainTextNeedsNoTemplate()
	{
		assertEquals("필터", TextLookup.translate(DATA, "Filters", Scope.of("interface", "mainTabs", "prayerTab")));
	}

	@Test
	public void keepsAPlayerNameWithDigits()
	{
		assertEquals("이름: AngryCat9605", TextLookup.translate(DATA, "Name: AngryCat9605", ACCOUNT));
	}

	@Test
	public void translatesNameSlotsAndKeepsColors()
	{
		assertEquals("몬스터: <col=ffffff>Giant Mole(자이언트 몰)</col>",
			TextLookup.translate(DATA, "Monster: <col=ffffff>Giant Mole</col>", COMBAT_ACHIEVEMENTS));
		assertEquals("Wintertodt(윈터토트) (1,234)", TextLookup.translate(DATA, "Wintertodt (1,234)", COMBAT_ACHIEVEMENTS));
	}

	@Test
	public void aSlotWithoutTranslationLeavesTheTextAlone()
	{
		assertNull(TextLookup.translate(DATA, "Monster: <col=ffffff>Nobody</col>", COMBAT_ACHIEVEMENTS));
	}

	@Test
	public void templatesStayInTheirOwnInterface()
	{
		// "<!ANY_TRANSLATED0> (<Num0>)" is for the combat achievements overview only.
		assertNull(TextLookup.translate(DATA, "Wintertodt (5)", Scope.of("interface", "mainTabs", "musicTab")));
	}
}

package com.runetongue.text;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class TranslationsTest
{
	private static TranslationTable table(String text)
	{
		return new TranslationTable(TsvParser.parse(text.getBytes(StandardCharsets.UTF_8)).getEntries());
	}

	private static Translations bundledOnly(String text)
	{
		return new Translations(TranslationTable.EMPTY, table(text));
	}

	private static final Scope HANS = Scope.of("dialogue", "Hans", "Hans");

	@Test
	public void mostSpecificScopeWinsWithinALayer()
	{
		Translations t = bundledOnly("Hello.\t안녕.\nHello.\t안녕하시오.\tdialogue\tHans\nHello.\t안녕하세요.\tactions\n");
		assertEquals("안녕하시오.", t.find("Hello.", HANS));
		assertEquals("안녕.", t.find("Hello.", Scope.of("dialogue", "Bob", "Bob")));
		assertEquals("안녕하세요.", t.find("Hello.", Scope.of("actions", "", "")));
		assertNull(t.find("Bye.", HANS));
	}

	@Test
	public void aLookupWithoutScopeFindsCategorizedLines()
	{
		Translations t = bundledOnly("Study\t연구하기\tactions\titem\tFire\n");
		assertEquals("연구하기", t.find("Study", Scope.ANY));
		assertEquals("연구하기", t.find("Study", Scope.of("actions", "item", "Bonfire")));
	}

	@Test
	public void looserMatchesStayInTheSameCategoryFirst()
	{
		Translations t = bundledOnly(
			"Attack\t공격!\tdialogue\tGuard\tGuard\n"
				+ "Attack\t공격하기\tactions\tnpc\tMan\n"
				+ "Hello.\t안녕하시오.\tdialogue\tHans\tHans\n");
		assertEquals("공격하기", t.find("Attack", Scope.of("actions", "npc", "Goblin")));
		assertEquals("공격!", t.find("Attack", Scope.of("dialogue", "Bob", "Bob")));
		assertEquals("안녕하시오.", t.find("Hello.", Scope.of("dialogue", "Hans", "Player")));
	}

	@Test
	public void aUserLineWithoutCategoryBeatsTheBundledData()
	{
		TranslationTable bundled = table("Talk-to\t대화하기\tactions\tnpc\tMan\n");
		Translations t = new Translations(table("Talk-to\t말 걸기\n"), bundled);
		assertEquals("말 걸기", t.find("Talk-to", Scope.of("actions", "npc", "Man")));
		assertEquals("말 걸기", t.find("Talk-to", Scope.ANY));
	}

	@Test
	public void aUserLineForOneCategoryDoesNotOverrideAnother()
	{
		TranslationTable bundled = table("Attack\t공격하기\tactions\tnpc\tMan\n");
		Translations t = new Translations(table("Attack\t공격!\tdialogue\n"), bundled);
		assertEquals("공격하기", t.find("Attack", Scope.of("actions", "npc", "Man")));
		assertEquals("공격!", t.find("Attack", Scope.of("dialogue", "Bob", "Bob")));
	}

	@Test
	public void laterFileWins()
	{
		List<Entry> both = new ArrayList<>(TsvParser.parse("Talk-to\t말 걸기\n".getBytes(StandardCharsets.UTF_8)).getEntries());
		both.addAll(TsvParser.parse("Talk-to\t대화하기\n".getBytes(StandardCharsets.UTF_8)).getEntries());
		assertEquals("대화하기", new Translations(new TranslationTable(both), TranslationTable.EMPTY).find("Talk-to", Scope.ANY));
	}
}

package com.runetongue.text;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

public class TsvParserTest
{
	private static ParseResult parse(String text)
	{
		return TsvParser.parse(text.getBytes(StandardCharsets.UTF_8));
	}

	private static List<String> pairs(ParseResult result)
	{
		return result.getEntries().stream()
			.map(e -> e.getEnglish() + " => " + e.getTranslation())
			.collect(Collectors.toList());
	}

	private static List<String> skips(ParseResult result)
	{
		return result.getSkipped().stream()
			.map(s -> s.getLine() + ":" + s.getReason())
			.collect(Collectors.toList());
	}

	@Test
	public void readsTwoColumnLinesWithoutHeader()
	{
		ParseResult r = parse("Talk-to\t대화하기\nHello there!\t안녕하세요!\n");
		assertEquals(List.of("Talk-to => 대화하기", "Hello there! => 안녕하세요!"), pairs(r));
		assertEquals(Scope.ANY, r.getEntries().get(0).getScope());
		assertEquals(List.of(), skips(r));
	}

	@Test
	public void headerSetsColumnOrderAndOptionalColumnsMayBeMissing()
	{
		ParseResult r = parse("category\ttranslation\tenglish\nactions\t대화하기\tTalk-to\n");
		assertEquals(List.of("Talk-to => 대화하기"), pairs(r));
		assertEquals(Scope.of("actions", "", ""), r.getEntries().get(0).getScope());

		ParseResult partial = parse("Talk-to\t대화하기\tactions\n");
		assertEquals(Scope.of("actions", "", ""), partial.getEntries().get(0).getScope());
	}

	@Test
	public void rawNumbersBecomePlaceholdersMatchedByValue()
	{
		ParseResult r = parse("Wave 5 of 10\t10 중 5번째 웨이브\nYou have 1,234 coins.\t코인 <Num0>개\n");
		assertEquals(List.of(
			"Wave <Num0> of <Num1> => <Num1> 중 <Num0>번째 웨이브",
			"You have <Num0> coins. => 코인 <Num0>개"), pairs(r));
	}

	@Test
	public void skipsPlaceholderMismatchButKeepsOtherLines()
	{
		ParseResult r = parse("You have 5 coins.\t코인이 있어요.\n"
			+ "Hi [player name].\t안녕.\n"
			+ "Hi [player name].\t안녕, [player name].\n");
		assertEquals(List.of("1:PLACEHOLDER_MISMATCH", "2:PLACEHOLDER_MISMATCH"), skips(r));
		assertEquals(List.of("Hi [player name]. => 안녕, [player name]."), pairs(r));
	}

	@Test
	public void emptyTranslationCountsAsUntranslatedNotAnError()
	{
		ParseResult r = parse("english\ttranslation\tcategory\nTalk-to\t\tactions\nAttack\t공격하기\tactions\n");
		assertEquals(1, r.getUntranslated());
		assertEquals(List.of(), skips(r));
		assertEquals(List.of("Attack => 공격하기"), pairs(r));
	}

	@Test
	public void laterDuplicateWinsAndEarlierIsReported()
	{
		ParseResult r = parse("Talk-to\t말 걸기\nTalk-to\t대화하기\nTalk-to\t대화\tactions\n");
		assertEquals(List.of("Talk-to => 대화하기", "Talk-to => 대화"), pairs(r));
		assertEquals(List.of("1:OVERRIDDEN"), skips(r));
	}

	@Test
	public void linesThatNormalizeToTheSameTranslationAreNotReported()
	{
		ParseResult r = parse("Take-1\t1개 가져가기\nTake-5\t5개 가져가기\n");
		assertEquals(List.of("Take-<Num0> => <Num0>개 가져가기"), pairs(r));
		assertEquals(List.of(), skips(r));
	}

	@Test
	public void badUtf8SkipsOnlyThatLine()
	{
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		bytes.writeBytes("Talk-to\t대화하기\n".getBytes(StandardCharsets.UTF_8));
		bytes.writeBytes("Attack\t".getBytes(StandardCharsets.UTF_8));
		bytes.writeBytes(new byte[]{(byte) 0xB0, (byte) 0xF8, (byte) 0xB0, (byte) 0xDD});
		bytes.writeBytes("\nUse\t사용하기\n".getBytes(StandardCharsets.UTF_8));
		ParseResult r = TsvParser.parse(bytes.toByteArray());
		assertEquals(List.of("2:BAD_ENCODING"), skips(r));
		assertEquals(List.of("Talk-to => 대화하기", "Use => 사용하기"), pairs(r));
	}

	@Test
	public void acceptsUtf8BomAndUtf16FromExcel()
	{
		byte[] bom = {(byte) 0xEF, (byte) 0xBB, (byte) 0xBF};
		byte[] body = "english\ttranslation\nTalk-to\t대화하기\n".getBytes(StandardCharsets.UTF_8);
		ByteArrayOutputStream utf8 = new ByteArrayOutputStream();
		utf8.writeBytes(bom);
		utf8.writeBytes(body);
		assertEquals(List.of("Talk-to => 대화하기"), pairs(TsvParser.parse(utf8.toByteArray())));

		ByteArrayOutputStream utf16 = new ByteArrayOutputStream();
		utf16.writeBytes(new byte[]{(byte) 0xFF, (byte) 0xFE});
		utf16.writeBytes("english\ttranslation\r\nTalk-to\t대화하기\r\n".getBytes(StandardCharsets.UTF_16LE));
		assertEquals(List.of("Talk-to => 대화하기"), pairs(TsvParser.parse(utf16.toByteArray())));
	}

	@Test
	public void unquotesExcelEscapedCells()
	{
		ParseResult r = parse("\"\"\"Cabbage!\"\" he says.\"\t\"\"\"양배추!\"\" 그가 말했다.\"\n\"Hi\"\t\"안녕\"\n");
		assertEquals(List.of("\"Cabbage!\" he says. => \"양배추!\" 그가 말했다.", "\"Hi\" => \"안녕\""), pairs(r));
	}

	@Test
	public void expandsChoicesPairwise()
	{
		ParseResult r = parse("Hello, [man/woman]! Thanks, [sir/madam].\t안녕, [젊은이/아가씨]! 고마워요, [선생님/부인].\n"
			+ "Good day, [sir/madam].\t안녕하세요.\n");
		assertEquals(List.of(
			"Hello, man! Thanks, sir. => 안녕, 젊은이! 고마워요, 선생님.",
			"Hello, woman! Thanks, madam. => 안녕, 아가씨! 고마워요, 부인.",
			"Good day, sir. => 안녕하세요.",
			"Good day, madam. => 안녕하세요."), pairs(r));
	}

	@Test
	public void skipsChoiceCountMismatch()
	{
		ParseResult r = parse("Hello, [man/woman].\t안녕, [젊은이/아가씨/어르신].\nHi [a/b] and [c/d/e].\t안녕.\n");
		assertEquals(List.of("1:CHOICE_MISMATCH", "2:CHOICE_MISMATCH"), skips(r));
	}

	@Test
	public void skipsMalformedLines()
	{
		ParseResult r = parse("only one column\n\t번역만 있음\n\n");
		assertEquals(List.of("1:TOO_FEW_COLUMNS", "2:EMPTY_ENGLISH"), skips(r));
		assertTrue(r.getEntries().isEmpty());
	}
}
